 5→//! NTT operations for Falcon-512 signature verification.
 6→//!
 7→//! Uses the auto-generated unrolled NTT (ntt_felt252) for n=512 only.
 8→//! No recursive NTT or INTT — verification uses hint-based approach.
 9→
10→use crate::ntt_felt252::ntt_512;
11→use crate::zq::{Zq, mul_mod};
12→
13→/// Multiply coefficients of two polynomials modulo Q (pointwise in NTT domain)
14→pub fn mul_ntt(mut f: Span<Zq>, mut g: Span<Zq>) -> Array<Zq> {
15→    assert(f.len() == g.len(), 'f.len() != g.len()');
16→    let mut res: Array<Zq> = array![];
17→    while let Some(f_coeff) = f.pop_front() {
18→        let g_coeff = g.pop_front().unwrap();
19→        res.append(mul_mod(*f_coeff, *g_coeff));
20→    }
21→    res
22→}
23→
24→/// Compute NTT of a 512-element polynomial using the unrolled felt252 implementation.
25→pub fn ntt_fast(f: Span<Zq>) -> Array<Zq> {
26→    assert(f.len() == 512, 'ntt_fast requires n=512');
27→    ntt_512(f)
28→}
29→
30→/// Verify an INTT result supplied as a hint.
31→/// Given f_ntt (NTT-domain polynomial) and result_hint (claimed coefficients),
32→/// verifies that NTT(result_hint) == f_ntt element-by-element.
33→/// Returns the verified result.
34→pub fn intt_with_hint(f_ntt: Span<Zq>, result_hint: Span<Zq>) -> Span<Zq> {
35→    assert(f_ntt.len() == result_hint.len(), 'length mismatch');
36→    let roundtrip = ntt_fast(result_hint);
37→    let mut f_iter = f_ntt;
38→    let mut r_iter = roundtrip.span();
39→    while let Some(f_val) = f_iter.pop_front() {
40→        assert(f_val == r_iter.pop_front().unwrap(), 'intt hint mismatch');
41→    }
42→    result_hint
43→}
