 50→type MulQAcc0 = BoundedInt<0, 151007232>;
 51→type MulQAcc1 = BoundedInt<0, 1855878881280>;
 52→type MulQAcc2 = BoundedInt<0, 22806895723057152>;
 53→type MulQAcc3 = BoundedInt<0, 280273941540800348160>;
 54→type MulQAcc4 = BoundedInt<0, 3444286467594895629545472>;
 55→type MulQAcc5 = BoundedInt<0, 42326836400273672391635312640>;
 56→type MulQAcc6 = BoundedInt<0, 520154492522963160020806508040192>;
 57→type MulQAcc7 = BoundedInt<0, 6392178558614694273495691177456926720>;
