343→### 4.1 `src/poseidon_hash.rs` — PoseidonHash
344→
345→Same XOF construction as Cairo. Base-Q extraction is trivial in Rust:
346→
347→```rust
348→const Q: u64 = 12289;
349→
350→pub struct PoseidonHash;
351→
352→impl PoseidonHash {
353→    pub fn hash_to_point(message: &[Felt], salt: &[Felt]) -> [u16; 512] {
354→        let mut state = [Felt::zero(); 3];
355→
356→        absorb(&mut state, message);
357→        absorb(&mut state, salt);
358→        state[2] += Felt::one();  // domain separation
359→
360→        let mut coeffs = [0u16; 512];
361→        let mut idx = 0;
362→        while idx < 512 {
363→            PoseidonCairoStark252::hades_permutation(&mut state);
364→            idx += extract_12_from_felt(&state[0], &mut coeffs, idx);
365→            if idx >= 512 { break; }
366→            idx += extract_12_from_felt(&state[1], &mut coeffs, idx);
367→        }
368→        coeffs
369→    }
370→}
371→
372→fn absorb(state: &mut [Felt; 3], input: &[Felt]) {
373→    let mut iter = input.iter();
374→    loop {
375→        match iter.next() {
376→            None => break,
377→            Some(first) => {
378→                state[0] += *first;
379→                match iter.next() {
380→                    Some(second) => state[1] += *second,
381→                    None => state[1] += Felt::one(),
382→                }
383→                PoseidonCairoStark252::hades_permutation(state);
384→            }
385→        }
386→    }
387→}
388→
389→fn extract_12_from_felt(value: &Felt, out: &mut [u16; 512], start: usize) -> usize {
390→    let bytes = value.to_bytes_be();
391→    let high = u128::from_be_bytes(bytes[0..16].try_into().unwrap());
392→    let low = u128::from_be_bytes(bytes[16..32].try_into().unwrap());
393→    let mut count = 0;
394→    count += extract_6_from_u128(low, out, start + count);
395→    count += extract_6_from_u128(high, out, start + count);
396→    count
397→}
398→
399→fn extract_6_from_u128(mut value: u128, out: &mut [u16; 512], start: usize) -> usize {
400→    for i in 0..6 {
401→        if start + i >= 512 { return i; }
402→        out[start + i] = (value % Q as u128) as u16;
403→        value /= Q as u128;
404→    }
405→    6
406→}
407→```
