360→        /// using the account's current public key.
361→        fn _is_valid_signature(
362→            self: @ComponentState<TContractState>, hash: felt252, signature: Span<felt252>,
363→        ) -> bool {
364→            let public_key = self.Account_public_key.read();
365→            is_valid_stark_signature(hash, public_key, signature)
