  1→//! Base-Q polynomial packing for storage-efficient Falcon public keys.
  2→//!
  3→//! Packs 512 Zq values into 29 felt252 slots using base Q=12289 encoding:
  4→//!   felt252 = pack_9(v0..v8) + pack_9(v9..v17) * 2^128
  5→//!
  6→//! DivRem by Q gives RemT = Zq directly — zero downcasts in the hot path.
  7→
  8→use corelib_imports::bounded_int::bounded_int::{add, mul};
  9→use corelib_imports::bounded_int::{
 10→    AddHelper, BoundedInt, DivRemHelper, MulHelper, bounded_int_div_rem, downcast, upcast,
 11→};
 12→use falcon::zq::{NZ_Q, QConst, Q_CONST, Zq};
 13→
 14→// =============================================================================
 15→// Constants
 16→// =============================================================================
 17→
 18→/// Number of Zq values per u128 half (Q^9 < 2^128)
 19→const VALS_PER_U128: usize = 9;
 20→
 21→/// Number of Zq values per felt252 (two u128 halves)
 22→const VALS_PER_FELT: usize = 18;
 23→
 24→/// Total felt252 slots for 512 values: ceil(512/18) = 29
 25→const PACKED_SLOTS: usize = 29;
 26→
 27→/// 2^128 as felt252 for combining u128 halves
 28→const TWO_POW_128: felt252 = 0x100000000000000000000000000000000;
 29→
 30→// =============================================================================
 31→// Accumulator type chain: AccN max = Q^(N+1) - 1
 32→// Shared between Horner packing and DivRem unpacking.
 33→// Acc0 = Zq (reused from zq.cairo)
 34→// =============================================================================
 35→
 36→type Acc0 = Zq; // BoundedInt<0, 12288>
 37→type Acc1 = BoundedInt<0, 151019520>;
 38→type Acc2 = BoundedInt<0, 1855878893568>;
 39→type Acc3 = BoundedInt<0, 22806895723069440>;
 40→type Acc4 = BoundedInt<0, 280273941540800360448>;
 41→type Acc5 = BoundedInt<0, 3444286467594895629557760>;
 42→type Acc6 = BoundedInt<0, 42326836400273672391635324928>;
 43→type Acc7 = BoundedInt<0, 520154492522963160020806508052480>;
 44→type Acc8 = BoundedInt<0, 6392178558614694273495691177456939008>;
 45→
 46→// =============================================================================
 47→// MulHelper intermediate types: MulQAccN max = Q * (Q^(N+1) - 1) = Q^(N+2) - Q
 48→// =============================================================================
 49→
 50→type MulQAcc0 = BoundedInt<0, 151007232>;
 51→type MulQAcc1 = BoundedInt<0, 1855878881280>;
 52→type MulQAcc2 = BoundedInt<0, 22806895723057152>;
 53→type MulQAcc3 = BoundedInt<0, 280273941540800348160>;
 54→type MulQAcc4 = BoundedInt<0, 3444286467594895629545472>;
 55→type MulQAcc5 = BoundedInt<0, 42326836400273672391635312640>;
 56→type MulQAcc6 = BoundedInt<0, 520154492522963160020806508040192>;
 57→type MulQAcc7 = BoundedInt<0, 6392178558614694273495691177456926720>;
 58→
 59→// =============================================================================
 60→// MulHelper impls: QConst * AccN -> MulQAccN
 61→// =============================================================================
 62→
 63→impl MulQAcc0Impl of MulHelper<QConst, Acc0> {
 64→    type Result = MulQAcc0;
 65→}
 66→
 67→impl MulQAcc1Impl of MulHelper<QConst, Acc1> {
 68→    type Result = MulQAcc1;
 69→}
 70→
 71→impl MulQAcc2Impl of MulHelper<QConst, Acc2> {
 72→    type Result = MulQAcc2;
 73→}
 74→
 75→impl MulQAcc3Impl of MulHelper<QConst, Acc3> {
 76→    type Result = MulQAcc3;
 77→}
 78→
 79→impl MulQAcc4Impl of MulHelper<QConst, Acc4> {
 80→    type Result = MulQAcc4;
 81→}
 82→
 83→impl MulQAcc5Impl of MulHelper<QConst, Acc5> {
 84→    type Result = MulQAcc5;
 85→}
 86→
 87→impl MulQAcc6Impl of MulHelper<QConst, Acc6> {
 88→    type Result = MulQAcc6;
 89→}
 90→
 91→impl MulQAcc7Impl of MulHelper<QConst, Acc7> {
 92→    type Result = MulQAcc7;
 93→}
 94→
 95→// =============================================================================
 96→// AddHelper impls: Zq + MulQAccN -> Acc(N+1)
 97→// Identity: (Q-1) + Q*(Q^(N+1)-1) = Q^(N+2) - 1
 98→// =============================================================================
 99→
100→impl AddZqMulQAcc0Impl of AddHelper<Zq, MulQAcc0> {
101→    type Result = Acc1;
102→}
103→
104→impl AddZqMulQAcc1Impl of AddHelper<Zq, MulQAcc1> {
105→    type Result = Acc2;
106→}
107→
108→impl AddZqMulQAcc2Impl of AddHelper<Zq, MulQAcc2> {
109→    type Result = Acc3;
110→}
111→
112→impl AddZqMulQAcc3Impl of AddHelper<Zq, MulQAcc3> {
113→    type Result = Acc4;
114→}
115→
116→impl AddZqMulQAcc4Impl of AddHelper<Zq, MulQAcc4> {
117→    type Result = Acc5;
118→}
119→
120→impl AddZqMulQAcc5Impl of AddHelper<Zq, MulQAcc5> {
121→    type Result = Acc6;
122→}
123→
124→impl AddZqMulQAcc6Impl of AddHelper<Zq, MulQAcc6> {
125→    type Result = Acc7;
126→}
127→
128→impl AddZqMulQAcc7Impl of AddHelper<Zq, MulQAcc7> {
129→    type Result = Acc8;
130→}
131→
132→// =============================================================================
133→// DivRemHelper impls: AccN / QConst -> (Acc(N-1), Zq)
134→// =============================================================================
135→
136→impl DivRemAcc1Impl of DivRemHelper<Acc1, QConst> {
137→    type DivT = Acc0;
138→    type RemT = Zq;
139→}
140→
141→impl DivRemAcc2Impl of DivRemHelper<Acc2, QConst> {
142→    type DivT = Acc1;
143→    type RemT = Zq;
144→}
145→
146→impl DivRemAcc3Impl of DivRemHelper<Acc3, QConst> {
147→    type DivT = Acc2;
148→    type RemT = Zq;
149→}
150→
151→impl DivRemAcc4Impl of DivRemHelper<Acc4, QConst> {
152→    type DivT = Acc3;
153→    type RemT = Zq;
154→}
155→
156→impl DivRemAcc5Impl of DivRemHelper<Acc5, QConst> {
157→    type DivT = Acc4;
158→    type RemT = Zq;
159→}
160→
161→impl DivRemAcc6Impl of DivRemHelper<Acc6, QConst> {
162→    type DivT = Acc5;
163→    type RemT = Zq;
164→}
165→
166→impl DivRemAcc7Impl of DivRemHelper<Acc7, QConst> {
167→    type DivT = Acc6;
168→    type RemT = Zq;
169→}
170→
171→impl DivRemAcc8Impl of DivRemHelper<Acc8, QConst> {
172→    type DivT = Acc7;
173→    type RemT = Zq;
174→}
175→
176→// =============================================================================
177→// Packing functions
178→// =============================================================================
179→
