  5→use corelib_imports::bounded_int::{BoundedInt, downcast, upcast};
  6→use falcon::types::{FalconPublicKey, FalconSignatureWithHint, HashToPoint};
  7→use crate::ntt::ntt_fast;
  8→use crate::zq::{Zq, mul_mod, sub_mod};
  9→
 10→/// Zq value in the low half: [0, (Q-1)/2] = [0, 6144]
 11→type ZqLow = BoundedInt<0, 6144>;
 12→const Q_felt252: felt252 = 12289;
 13→
 14→/// Compute the squared centered norm of a single Zq element.
 15→#[inline(always)]
 16→fn center_and_square(coeff: Zq) -> felt252 {
 17→    match downcast::<Zq, ZqLow>(coeff) {
 18→        Option::Some(low) => {
 19→            let x: felt252 = upcast(low);
 20→            x * x
 21→        },
 22→        Option::None => {
 23→            let x: felt252 = upcast(coeff);
 24→            let centered = Q_felt252 - x;
 25→            centered * centered
 26→        },
 27→    }
 28→}
 29→
 30→/// Signature bound for Falcon-512
 31→const SIG_BOUND_512: u64 = 34034726;
 32→
 33→/// Verify a Falcon signature using the hint-based approach.
 34→/// Computes msg_point internally via hash_to_point.
 35→/// Cost: 2 NTTs, 0 INTTs.
 36→pub fn verify<H, +HashToPoint<H>, +Drop<H>>(
 37→    pk: @FalconPublicKey, sig_with_hint: FalconSignatureWithHint, message: Span<felt252>,
 38→) -> bool {
 39→    let msg_point = HashToPoint::<H>::hash_to_point(message, sig_with_hint.signature.salt.span());
 40→    verify_with_msg_point(pk, sig_with_hint, msg_point.span())
 41→}
 42→
 43→/// Verify with a pre-computed msg_point (useful for testing without hash_to_point).
 44→///
 45→/// Single-pass verification: 2 unrolled NTTs + 1 fused loop that does
 46→/// hint verification, pointwise multiply check, and norm computation.
 47→pub fn verify_with_msg_point(
 48→    pk: @FalconPublicKey, sig_with_hint: FalconSignatureWithHint, msg_point: Span<Zq>,
 49→) -> bool {
 50→    let s1 = sig_with_hint.signature.s1.span();
 51→    let pk_ntt = pk.h_ntt.span();
 52→    let mul_hint = sig_with_hint.hint.mul_hint.span();
 53→
 54→    assert!(s1.len() == 512, "s1 must be 512 elements");
 55→    assert!(pk_ntt.len() == 512, "pk must be 512 elements");
 56→    assert!(mul_hint.len() == 512, "mul_hint must be 512 elements");
 57→    assert!(msg_point.len() == 512, "msg_point must be 512 elements");
 58→
 59→    // Two forward NTTs (unrolled, no loops)
 60→    let s1_ntt = ntt_fast(s1);
 61→    let hint_ntt = ntt_fast(mul_hint);
 62→
 63→    // Single pass over all 512 coefficients:
 64→    //   - Verify hint: s1_ntt[i] * pk_ntt[i] == NTT(mul_hint)[i]
 65→    //   - Accumulate: ||msg_point - mul_hint||² + ||s1||²
 66→    let mut s1_ntt_iter = s1_ntt.span();
 67→    let mut pk_ntt_iter = pk_ntt;
 68→    let mut hint_ntt_iter = hint_ntt.span();
 69→    let mut msg_iter = msg_point;
 70→    let mut hint_iter = mul_hint;
 71→    let mut s1_iter = s1;
 72→
 73→    let mut acc: felt252 = 0;
 74→    while let Some(s1n_box) = s1_ntt_iter.multi_pop_front::<8>() {
 75→        let [s1n0, s1n1, s1n2, s1n3, s1n4, s1n5, s1n6, s1n7] = s1n_box.unbox();
 76→        let [pkn0, pkn1, pkn2, pkn3, pkn4, pkn5, pkn6, pkn7] = pk_ntt_iter
 77→            .multi_pop_front::<8>()
 78→            .unwrap()
 79→            .unbox();
 80→        let [hn0, hn1, hn2, hn3, hn4, hn5, hn6, hn7] = hint_ntt_iter
 81→            .multi_pop_front::<8>()
 82→            .unwrap()
 83→            .unbox();
 84→        let [msg0, msg1, msg2, msg3, msg4, msg5, msg6, msg7] = msg_iter
 85→            .multi_pop_front::<8>()
 86→            .unwrap()
 87→            .unbox();
 88→        let [hint0, hint1, hint2, hint3, hint4, hint5, hint6, hint7] = hint_iter
 89→            .multi_pop_front::<8>()
 90→            .unwrap()
 91→            .unbox();
 92→        let [s1v0, s1v1, s1v2, s1v3, s1v4, s1v5, s1v6, s1v7] = s1_iter
 93→            .multi_pop_front::<8>()
 94→            .unwrap()
 95→            .unbox();
 96→
 97→        // Verify: NTT(s1)[i] * pk_ntt[i] == NTT(mul_hint)[i]
 98→        assert(mul_mod(s1n0, pkn0) == hn0, 'hint mismatch');
 99→        assert(mul_mod(s1n1, pkn1) == hn1, 'hint mismatch');
100→        assert(mul_mod(s1n2, pkn2) == hn2, 'hint mismatch');
101→        assert(mul_mod(s1n3, pkn3) == hn3, 'hint mismatch');
102→        assert(mul_mod(s1n4, pkn4) == hn4, 'hint mismatch');
103→        assert(mul_mod(s1n5, pkn5) == hn5, 'hint mismatch');
104→        assert(mul_mod(s1n6, pkn6) == hn6, 'hint mismatch');
105→        assert(mul_mod(s1n7, pkn7) == hn7, 'hint mismatch');
106→
107→        // Accumulate: ||msg_point - mul_hint||² + ||s1||²
108→        acc += center_and_square(sub_mod(msg0, hint0))
109→            + center_and_square(s1v0)
110→            + center_and_square(sub_mod(msg1, hint1))
111→            + center_and_square(s1v1)
112→            + center_and_square(sub_mod(msg2, hint2))
113→            + center_and_square(s1v2)
114→            + center_and_square(sub_mod(msg3, hint3))
115→            + center_and_square(s1v3)
116→            + center_and_square(sub_mod(msg4, hint4))
117→            + center_and_square(s1v4)
118→            + center_and_square(sub_mod(msg5, hint5))
119→            + center_and_square(s1v5)
120→            + center_and_square(sub_mod(msg6, hint6))
121→            + center_and_square(s1v6)
122→            + center_and_square(sub_mod(msg7, hint7))
123→            + center_and_square(s1v7);
124→    }
125→
126→    let norm_u64: u64 = acc.try_into().unwrap();
127→    norm_u64 <= SIG_BOUND_512
128→}
