  5→//! Operations on the base ring Z_q using BoundedInt with lazy modular reduction
  6→
  7→use corelib_imports::bounded_int::bounded_int::{SubHelper, add, mul, sub};
  8→use corelib_imports::bounded_int::{
  9→    AddHelper, BoundedInt, DivRemHelper, MulHelper, UnitInt, bounded_int_div_rem, downcast, upcast,
 10→};
 11→
 12→/// BoundedInt type for elements in Z_q: [0, Q-1] = [0, 12288]
 13→pub type Zq = BoundedInt<0, 12288>;
 14→
 15→/// Singleton type for the modulus Q
 16→pub type QConst = UnitInt<12289>;
 17→
 18→/// Constant Q as BoundedInt
 19→pub const Q_CONST: QConst = 12289;
 20→
 21→/// Q as a NonZero constant for division
 22→pub const NZ_Q: NonZero<QConst> = 12289;
 23→
 24→// =============================================================================
 25→// Type conversion utilities
 26→// =============================================================================
 27→
 28→/// Convert u16 to Zq (requires range check - use only at deserialization boundaries)
 29→#[inline(always)]
 30→pub fn from_u16(x: u16) -> Zq {
 31→    downcast(x).expect('value exceeds Q-1')
 32→}
 33→
 34→// =============================================================================
 35→// Intermediate bound types for lazy reduction
 36→// =============================================================================
 37→
 38→/// Sum of two Zq values: [0, 24576]
 39→pub type ZqSum = BoundedInt<0, 24576>;
 40→
 41→/// Difference after adding offset Q: (a + Q) - b gives [1, 24577]
 42→pub type ZqDiffOffset = BoundedInt<1, 24577>;
 43→
 44→/// Product of two Zq values: [0, 150994944]
 45→pub type ZqProd = BoundedInt<0, 150994944>;
 46→
 47→// =============================================================================
 48→// AddHelper implementations
 49→// =============================================================================
 50→
 51→impl AddZqZqImpl of AddHelper<Zq, Zq> {
 52→    type Result = ZqSum;
 53→}
 54→
 55→impl AddZqQImpl of AddHelper<Zq, QConst> {
 56→    type Result = BoundedInt<12289, 24577>;
 57→}
 58→
 59→// =============================================================================
 60→// SubHelper implementations
 61→// =============================================================================
 62→
 63→impl SubZqOffsetZqImpl of SubHelper<BoundedInt<12289, 24577>, Zq> {
 64→    type Result = ZqDiffOffset;
 65→}
 66→
 67→// =============================================================================
 68→// MulHelper implementations
 69→// =============================================================================
 70→
 71→impl MulZqZqImpl of MulHelper<Zq, Zq> {
 72→    type Result = ZqProd;
 73→}
 74→
 75→// =============================================================================
 76→// DivRemHelper implementations for modular reduction
 77→// =============================================================================
 78→
 79→impl DivRemZqProdImpl of DivRemHelper<ZqProd, QConst> {
 80→    type DivT = BoundedInt<0, 12287>;
 81→    type RemT = Zq;
 82→}
 83→
 84→impl DivRemZqSumImpl of DivRemHelper<ZqSum, QConst> {
 85→    type DivT = BoundedInt<0, 1>;
 86→    type RemT = Zq;
 87→}
