 94→// =============================================================================
 95→// Modular arithmetic operations (BoundedInt in, BoundedInt out)
 96→// =============================================================================
 97→
 98→/// Add two Zq values and reduce mod Q
 99→#[inline(always)]
100→pub fn add_mod(a: Zq, b: Zq) -> Zq {
101→    let sum: ZqSum = add(a, b);
102→    let (_q, rem) = bounded_int_div_rem(sum, NZ_Q);
103→    rem
104→}
105→
106→/// Subtract two Zq values and reduce mod Q
107→/// Uses the identity: (a - b) mod Q = (a + Q - b) mod Q
108→#[inline(always)]
109→pub fn sub_mod(a: Zq, b: Zq) -> Zq {
110→    let a_plus_q: BoundedInt<12289, 24577> = add(a, Q_CONST);
111→    let diff: ZqDiffOffset = sub(a_plus_q, b);
112→    let (_q, rem) = bounded_int_div_rem(diff, NZ_Q);
113→    rem
114→}
115→
116→/// Multiply two Zq values and reduce mod Q
117→#[inline(always)]
118→pub fn mul_mod(a: Zq, b: Zq) -> Zq {
119→    let prod: ZqProd = mul(a, b);
120→    let (_q, rem) = bounded_int_div_rem(prod, NZ_Q);
121→    rem
122→}
