 24→fn load_args() -> Args {
 25→    let file = FileTrait::new("tests/data/args_512_1_int.json");
 26→    let serialized = read_json(@file);
 27→    let mut span = serialized.span();
 28→    let _header = span.pop_front();
 29→    Serde::deserialize(ref span).expect('deserialize failed')
 30→}
