 32→/// Convert u16 span to Zq array (only place u16→Zq conversion lives in tests)
 33→fn to_zq_array(s: Span<u16>) -> Array<Zq> {
 34→    let mut r: Array<Zq> = array![];
 35→    for v in s {
 36→        r.append(from_u16(*v));
 37→    }
 38→    r
 39→}
 40→
 41→/// Convert Zq span to u16 array (for falcon_old interop)
 42→fn to_u16_array(s: Span<Zq>) -> Array<u16> {
 43→    let mut r: Array<u16> = array![];
 44→    for v in s {
 45→        r.append(upcast(*v));
 46→    }
 47→    r
 48→}
