 1→use falcon::packing::{pack_public_key, unpack_public_key};
 2→use falcon::zq::{Zq, from_u16};
 3→
 4→#[test]
 5→fn test_packing_roundtrip_simple() {
 6→    let mut values: Array<Zq> = array![
 7→        from_u16(0), from_u16(1), from_u16(2), from_u16(100), from_u16(12288), from_u16(6000),
 8→        from_u16(3000), from_u16(9999), from_u16(5555), from_u16(42), from_u16(7777),
 9→        from_u16(11111), from_u16(0), from_u16(12288), from_u16(1234), from_u16(5678),
10→        from_u16(8888), from_u16(4321),
11→    ];
12→    let mut i: usize = 18;
13→    while i != 512 {
14→        values.append(from_u16((i % 12289).try_into().unwrap()));
15→        i += 1;
16→    }
17→
18→    let packed = pack_public_key(values.span());
19→    assert_eq!(packed.len(), 29);
20→
21→    let unpacked = unpack_public_key(packed.span());
22→    assert_eq!(unpacked.len(), 512);
23→
24→    let mut j: usize = 0;
25→    while j != 512 {
26→        assert_eq!(*unpacked.at(j), *values.at(j), "mismatch at index {}", j);
27→        j += 1;
28→    };
29→}
