254→        fn get_public_key(self: @ComponentState<TContractState>) -> felt252 {
255→            PublicKey::get_public_key(self)
256→        }
257→
258→        fn set_public_key(
259→            ref self: ComponentState<TContractState>,
260→            new_public_key: felt252,
261→            signature: Span<felt252>,
262→        ) {
263→            PublicKey::set_public_key(ref self, new_public_key, signature);
264→        }
265→
266→        // IPublicKeyCamel
267→        fn getPublicKey(self: @ComponentState<TContractState>) -> felt252 {
268→            PublicKeyCamel::getPublicKey(self)
269→        }
270→
271→        fn setPublicKey(
272→            ref self: ComponentState<TContractState>,
273→            newPublicKey: felt252,
274→            signature: Span<felt252>,
275→        ) {
276→            PublicKeyCamel::setPublicKey(ref self, newPublicKey, signature);
277→        }
278→
279→        // ISRC5
280→        fn supports_interface(
281→            self: @ComponentState<TContractState>, interface_id: felt252,
282→        ) -> bool {
283→            let src5 = get_dep_component!(self, SRC5);
284→            src5.supports_interface(interface_id)
285→        }
286→    }
287→
288→    //
289→    // Internal
290→    //
291→
292→    #[generate_trait]
293→    pub impl InternalImpl<
294→        TContractState,
295→        +HasComponent<TContractState>,
296→        impl SRC5: SRC5Component::HasComponent<TContractState>,
297→        +Drop<TContractState>,
298→    > of InternalTrait<TContractState> {
299→        /// Initializes the account with the given public key, and registers the ISRC6 interface ID.
300→        ///
301→        /// Emits an `OwnerAdded` event.
302→        fn initializer(ref self: ComponentState<TContractState>, public_key: felt252) {
303→            let mut src5_component = get_dep_component_mut!(ref self, SRC5);
304→            src5_component.register_interface(interface::ISRC6_ID);
305→            self._set_public_key(public_key);
306→        }
307→
308→        /// Validates that the caller is the account itself. Otherwise it reverts.
309→        fn assert_only_self(self: @ComponentState<TContractState>) {
310→            let caller = starknet::get_caller_address();
311→            let self = starknet::get_contract_address();
312→            assert(self == caller, Errors::UNAUTHORIZED);
313→        }
314→
315→        /// Validates that `new_owner` accepted the ownership of the contract.
316→        ///
317→        /// WARNING: This function assumes that `current_owner` is the current owner of the
318→        /// contract, and does not validate this assumption.
319→        ///
320→        /// Requirements:
321→        ///
322→        /// - The signature must be valid for the new owner.
323→        fn assert_valid_new_owner(
324→            self: @ComponentState<TContractState>,
325→            current_owner: felt252,
326→            new_owner: felt252,
327→            signature: Span<felt252>,
328→        ) {
329→            let message_hash = PoseidonTrait::new()
330→                .update_with('StarkNet Message')
331→                .update_with('accept_ownership')
332→                .update_with(starknet::get_contract_address())
333→                .update_with(current_owner)
334→                .finalize();
335→
336→            let is_valid = is_valid_stark_signature(message_hash, new_owner, signature);
337→            assert(is_valid, Errors::INVALID_SIGNATURE);
338→        }
339→
340→        /// Validates the signature for the current transaction.
341→        /// Returns the short string `VALID` if valid, otherwise it reverts.
342→        fn validate_transaction(self: @ComponentState<TContractState>) -> felt252 {
343→            let tx_info = starknet::get_tx_info().unbox();
344→            let tx_hash = tx_info.transaction_hash;
345→            let signature = tx_info.signature;
346→            assert(self._is_valid_signature(tx_hash, signature), Errors::INVALID_SIGNATURE);
347→            starknet::VALIDATED
348→        }
349→
350→        /// Sets the public key without validating the caller.
351→        /// The usage of this method outside the `set_public_key` function is discouraged.
352→        ///
353→        /// Emits an `OwnerAdded` event.
354→        fn _set_public_key(ref self: ComponentState<TContractState>, new_public_key: felt252) {
355→            self.Account_public_key.write(new_public_key);
356→            self.emit(OwnerAdded { new_owner_guid: new_public_key });
357→        }
358→
359→        /// Returns whether the given signature is valid for the given hash
360→        /// using the account's current public key.
361→        fn _is_valid_signature(
362→            self: @ComponentState<TContractState>, hash: felt252, signature: Span<felt252>,
363→        ) -> bool {
364→            let public_key = self.Account_public_key.read();
365→            is_valid_stark_signature(hash, public_key, signature)
366→        }
367→    }
368→}
