 9→pub const MIN_TRANSACTION_VERSION: u256 = 1;
10→pub const QUERY_OFFSET: u256 = 0x100000000000000000000000000000000;
11→// QUERY_OFFSET + TRANSACTION_VERSION
12→pub const QUERY_VERSION: u256 = 0x100000000000000000000000000000001;
13→
14→/// If the transaction is a simulation (version >= `QUERY_OFFSET`), it must be
15→/// greater than or equal to `QUERY_OFFSET` + `MIN_TRANSACTION_VERSION` to be considered valid.
16→/// Otherwise, it must be greater than or equal to `MIN_TRANSACTION_VERSION`.
17→pub fn is_tx_version_valid() -> bool {
18→    let tx_info = starknet::get_tx_info().unbox();
19→    let tx_version = tx_info.version.into();
20→    if tx_version >= QUERY_OFFSET {
21→        QUERY_OFFSET + MIN_TRANSACTION_VERSION <= tx_version
22→    } else {
23→        MIN_TRANSACTION_VERSION <= tx_version
24→    }
25→}
