 8→pub mod SRC5Component {
 9→    use openzeppelin_interfaces::introspection as interface;
10→    use starknet::storage::{Map, StorageMapReadAccess, StorageMapWriteAccess};
11→
12→    #[storage]
13→    pub struct Storage {
14→        pub SRC5_supported_interfaces: Map<felt252, bool>,
15→    }
16→
17→    pub mod Errors {
18→        pub const INVALID_ID: felt252 = 'SRC5: invalid id';
19→    }
20→
21→    //
22→    // External
23→    //
24→
25→    #[embeddable_as(SRC5Impl)]
26→    impl SRC5<
27→        TContractState, +HasComponent<TContractState>,
28→    > of interface::ISRC5<ComponentState<TContractState>> {
29→        /// Returns whether the contract implements the given interface.
30→        fn supports_interface(
31→            self: @ComponentState<TContractState>, interface_id: felt252,
32→        ) -> bool {
33→            if interface_id == interface::ISRC5_ID {
34→                return true;
35→            }
36→            self.SRC5_supported_interfaces.read(interface_id)
37→        }
38→    }
39→
40→    //
41→    // Internal
42→    //
43→
44→    #[generate_trait]
45→    pub impl InternalImpl<
46→        TContractState, +HasComponent<TContractState>,
47→    > of InternalTrait<TContractState> {
48→        /// Registers the given interface as supported by the contract.
49→        fn register_interface(ref self: ComponentState<TContractState>, interface_id: felt252) {
50→            self.SRC5_supported_interfaces.write(interface_id, true);
51→        }
52→
53→        /// Deregisters the given interface as supported by the contract.
54→        ///
55→        /// Requirements:
