58→        fn deregister_interface(ref self: ComponentState<TContractState>, interface_id: felt252) {
59→            assert(interface_id != interface::ISRC5_ID, Errors::INVALID_ID);
60→            self.SRC5_supported_interfaces.write(interface_id, false);
61→        }
62→    }
