 8→/// Executes a list of calls and returns the return values.
 9→pub fn execute_calls(calls: Span<Call>) -> Array<Span<felt252>> {
10→    let mut res = array![];
11→    for call in calls {
12→        res.append(execute_single_call(call));
13→    }
14→    res
15→}
16→
17→/// Executes a single call and returns the return value.
18→pub fn execute_single_call(call: @Call) -> Span<felt252> {
19→    let Call { to, selector, calldata } = *call;
20→    starknet::syscalls::call_contract_syscall(to, selector, calldata).unwrap_syscall()
21→}
22→
23→/// Validates a signature using SRC6 `is_valid_signature` and asserts it's valid.
24→/// Checks both 'VALID' (starknet::VALIDATED) and true (1) for backwards compatibility.
25→pub fn assert_valid_signature(
26→    signer: ContractAddress,
27→    hash: felt252,
28→    signature: Span<felt252>,
29→    invalid_signature_error: felt252,
30→) {
31→    let is_valid_signature_felt = ISRC6Dispatcher { contract_address: signer }
32→        .is_valid_signature(hash, signature.into());
33→
34→    // Check either 'VALID' or true for backwards compatibility
35→    let is_valid_signature = is_valid_signature_felt == starknet::VALIDATED
36→        || is_valid_signature_felt == 1;
37→
38→    assert(is_valid_signature, invalid_signature_error);
39→}
