309→/// Pack 512 Zq values into 29 felt252 slots.
310→/// Each slot encodes up to 18 values: pack_9(lo) + pack_9(hi) * 2^128.
311→pub fn pack_public_key(values: Span<Zq>) -> Array<felt252> {
312→    assert!(values.len() == 512, "expected 512 values");
313→    let mut result: Array<felt252> = array![];
314→    let mut offset: usize = 0;
315→    // 28 full slots of 18 values each = 504 values
316→    // 1 final slot with 8 remaining values
317→    let total = 512;
318→    while offset != total {
319→        let remaining = total - offset;
320→        let chunk = if remaining >= VALS_PER_FELT {
321→            VALS_PER_FELT
322→        } else {
323→            remaining
324→        };
325→        let lo_count = if chunk >= VALS_PER_U128 {
326→            VALS_PER_U128
327→        } else {
328→            chunk
329→        };
330→        let hi_count = chunk - lo_count;
331→
332→        let lo_packed = pack_9(values.slice(offset, lo_count));
333→        let lo_felt: felt252 = lo_packed.into();
334→
335→        let slot = if hi_count != 0 {
336→            let hi_packed = pack_9(values.slice(offset + lo_count, hi_count));
337→            let hi_felt: felt252 = hi_packed.into();
338→            lo_felt + hi_felt * TWO_POW_128
339→        } else {
340→            lo_felt
341→        };
342→
343→        result.append(slot);
344→        offset += chunk;
345→    }
346→    assert!(result.len() == PACKED_SLOTS, "packing produced wrong slot count");
347→    result
348→}
349→
350→/// Unpack 29 felt252 slots back to 512 Zq values.
351→pub fn unpack_public_key(packed: Span<felt252>) -> Array<Zq> {
352→    let mut output: Array<Zq> = array![];
353→    let mut remaining: usize = 512;
354→    let mut i: usize = 0;
355→    let slot_count = packed.len();
356→    while i != slot_count {
357→        let value: felt252 = *packed.at(i);
358→        let val_u256: u256 = value.into();
359→        let low: u128 = val_u256.low;
360→        let high: u128 = val_u256.high;
361→
362→        let lo_count = if remaining >= VALS_PER_U128 {
363→            VALS_PER_U128
364→        } else {
365→            remaining
366→        };
367→        unpack_9(low, lo_count, ref output);
368→        remaining -= lo_count;
369→
370→        let hi_count = if remaining >= VALS_PER_U128 {
371→            VALS_PER_U128
372→        } else {
373→            remaining
374→        };
375→        if hi_count != 0 {
376→            unpack_9(high, hi_count, ref output);
377→            remaining -= hi_count;
378→        }
379→
380→        i += 1;
381→    }
382→    output
383→}
