350→/// Unpack 29 felt252 slots back to 512 Zq values.
351→pub fn unpack_public_key(packed: Span<felt252>) -> Array<Zq> {
352→    let mut output: Array<Zq> = array![];
353→    let mut remaining: usize = 512;
354→    let mut i: usize = 0;
355→    let slot_count = packed.len();
356→    while i != slot_count {
357→        let value: felt252 = *packed.at(i);
358→        let val_u256: u256 = value.into();
359→        let low: u128 = val_u256.low;
