386→// PackedPolynomial512: storage-friendly struct for 512 Zq coefficients
387→// =============================================================================
388→
389→/// A polynomial of 512 Zq coefficients packed into 29 felt252 fields.
390→/// Suitable for Starknet storage (each field maps to a single storage slot).
391→#[derive(Drop, Copy, Serde)]
392→pub struct PackedPolynomial512 {
393→    pub s0: felt252,
394→    pub s1: felt252,
395→    pub s2: felt252,
396→    pub s3: felt252,
397→    pub s4: felt252,
398→    pub s5: felt252,
399→    pub s6: felt252,
400→    pub s7: felt252,
401→    pub s8: felt252,
402→    pub s9: felt252,
403→    pub s10: felt252,
404→    pub s11: felt252,
405→    pub s12: felt252,
406→    pub s13: felt252,
407→    pub s14: felt252,
408→    pub s15: felt252,
409→    pub s16: felt252,
410→    pub s17: felt252,
411→    pub s18: felt252,
412→    pub s19: felt252,
413→    pub s20: felt252,
414→    pub s21: felt252,
415→    pub s22: felt252,
416→    pub s23: felt252,
417→    pub s24: felt252,
418→    pub s25: felt252,
419→    pub s26: felt252,
420→    pub s27: felt252,
421→    pub s28: felt252,
422→}
423→
424→#[generate_trait]
425→pub impl PackedPolynomial512Impl of PackedPolynomial512Trait {
426→    /// Pack 512 Zq coefficients into a `PackedPolynomial512`.
427→    fn from_coeffs(values: Span<Zq>) -> PackedPolynomial512 {
428→        let packed = pack_public_key(values);
429→        let s = packed.span();
430→        PackedPolynomial512 {
431→            s0: *s.at(0),
432→            s1: *s.at(1),
433→            s2: *s.at(2),
434→            s3: *s.at(3),
435→            s4: *s.at(4),
436→            s5: *s.at(5),
437→            s6: *s.at(6),
438→            s7: *s.at(7),
439→            s8: *s.at(8),
440→            s9: *s.at(9),
441→            s10: *s.at(10),
442→            s11: *s.at(11),
443→            s12: *s.at(12),
444→            s13: *s.at(13),
445→            s14: *s.at(14),
446→            s15: *s.at(15),
447→            s16: *s.at(16),
448→            s17: *s.at(17),
449→            s18: *s.at(18),
450→            s19: *s.at(19),
451→            s20: *s.at(20),
452→            s21: *s.at(21),
453→            s22: *s.at(22),
454→            s23: *s.at(23),
455→            s24: *s.at(24),
456→            s25: *s.at(25),
457→            s26: *s.at(26),
458→            s27: *s.at(27),
459→            s28: *s.at(28),
460→        }
461→    }
462→
463→    /// Unpack back to 512 Zq coefficients.
464→    fn to_coeffs(self: @PackedPolynomial512) -> Array<Zq> {
465→        unpack_public_key(self.to_span())
466→    }
467→
468→    /// Return the 29 packed felt252 values as a span.
469→    fn to_span(self: @PackedPolynomial512) -> Span<felt252> {
470→        array![
471→            *self.s0, *self.s1, *self.s2, *self.s3, *self.s4, *self.s5, *self.s6, *self.s7,
