  1→use corelib_imports::bounded_int::upcast;
  2→use falcon::falcon::verify_with_msg_point;
  3→use falcon::ntt::{mul_ntt, ntt_fast};
  4→use falcon::types::{
  5→    FalconPublicKey, FalconSignature, FalconSignatureWithHint, FalconVerificationHint,
  6→};
  7→use falcon::zq::{Zq, from_u16};
  8→use falcon_old::ntt::intt;
  9→use snforge_std::fs::{FileTrait, read_json};
 10→
 11→#[derive(Drop, Serde)]
 12→struct Args {
 13→    attestations: Array<Attestation>,
 14→    n: u32,
 15→}
 16→
 17→#[derive(Drop, Serde)]
 18→struct Attestation {
 19→    s1: Array<u16>,
 20→    pk: Array<u16>,
 21→    msg_point: Array<u16>,
 22→}
 23→
 24→fn load_args() -> Args {
 25→    let file = FileTrait::new("tests/data/args_512_1_int.json");
 26→    let serialized = read_json(@file);
 27→    let mut span = serialized.span();
 28→    let _header = span.pop_front();
 29→    Serde::deserialize(ref span).expect('deserialize failed')
 30→}
 31→
 32→/// Convert u16 span to Zq array (only place u16→Zq conversion lives in tests)
 33→fn to_zq_array(s: Span<u16>) -> Array<Zq> {
 34→    let mut r: Array<Zq> = array![];
 35→    for v in s {
 36→        r.append(from_u16(*v));
 37→    }
 38→    r
 39→}
 40→
 41→/// Convert Zq span to u16 array (for falcon_old interop)
 42→fn to_u16_array(s: Span<Zq>) -> Array<u16> {
 43→    let mut r: Array<u16> = array![];
 44→    for v in s {
 45→        r.append(upcast(*v));
 46→    }
 47→    r
 48→}
 49→
 50→#[test]
 51→fn test_verify_with_msg_point() {
 52→    let args = load_args();
 53→    let att = args.attestations.at(0);
 54→
 55→    // Convert u16 test data to Zq for the new API
 56→    let pk_zq = to_zq_array(att.pk.span());
 57→    let s1_zq = to_zq_array(att.s1.span());
 58→
 59→    // Test data has pk in coefficient domain; convert to NTT domain
 60→    let pk_ntt = ntt_fast(pk_zq.span());
 61→
 62→    // Compute mul_hint = INTT(NTT(s1) * pk_ntt)
 63→    // ntt_fast and mul_ntt return Array<Zq>; falcon_old::intt needs Span<u16>
 64→    let s1_ntt = ntt_fast(s1_zq.span());
 65→    let product_ntt = mul_ntt(s1_ntt.span(), pk_ntt.span());
 66→    let product_ntt_u16 = to_u16_array(product_ntt.span());
 67→    let mul_hint_u16 = intt(product_ntt_u16.span());
 68→
 69→    // Convert hint back to Zq for the struct
 70→    let hint_arr = to_zq_array(mul_hint_u16);
 71→
 72→    // Clone s1 and pk_ntt for the struct
 73→    let mut s1_arr: Array<Zq> = array![];
 74→    for v in s1_zq.span() {
 75→        s1_arr.append(*v);
 76→    }
 77→    let mut pk_ntt_arr: Array<Zq> = array![];
 78→    for v in pk_ntt.span() {
 79→        pk_ntt_arr.append(*v);
 80→    }
 81→
 82→    let msg_point_zq = to_zq_array(att.msg_point.span());
 83→
 84→    let pk = FalconPublicKey { h_ntt: pk_ntt_arr };
 85→    let sig = FalconSignature { s1: s1_arr, salt: array![] };
 86→    let hint = FalconVerificationHint { mul_hint: hint_arr };
 87→    let sig_with_hint = FalconSignatureWithHint { signature: sig, hint };
 88→
 89→    let result = verify_with_msg_point(@pk, sig_with_hint, msg_point_zq.span());
 90→    assert!(result, "verification should pass");
 91→}
 92→
 93→#[test]
 94→#[should_panic(expected: 'hint mismatch')]
 95→fn test_verify_bad_hint_panics() {
 96→    let args = load_args();
 97→    let att = args.attestations.at(0);
 98→
 99→    let pk_zq = to_zq_array(att.pk.span());
100→    let pk_ntt = ntt_fast(pk_zq.span());
101→
102→    // Build a WRONG hint (all zeros — won't match NTT(s1) * pk_ntt)
103→    let zero: Zq = from_u16(0);
104→    let mut bad_hint: Array<Zq> = array![];
105→    let mut i: usize = 0;
106→    while i != 512 {
107→        bad_hint.append(zero);
108→        i += 1;
109→    }
110→
111→    let s1_arr = to_zq_array(att.s1.span());
112→    let mut pk_ntt_arr: Array<Zq> = array![];
113→    for v in pk_ntt.span() {
114→        pk_ntt_arr.append(*v);
115→    }
116→
117→    let msg_point_zq = to_zq_array(att.msg_point.span());
118→
119→    let pk = FalconPublicKey { h_ntt: pk_ntt_arr };
120→    let sig = FalconSignature { s1: s1_arr, salt: array![] };
121→    let hint = FalconVerificationHint { mul_hint: bad_hint };
122→    let sig_with_hint = FalconSignatureWithHint { signature: sig, hint };
123→
124→    // This should panic with 'intt hint mismatch' because NTT(zeros) != s1_ntt * pk_ntt
125→    verify_with_msg_point(@pk, sig_with_hint, msg_point_zq.span());
126→}
