 49→#[test]
 50→fn test_hash_to_point_matches_rust() {
 51→    let test = load_hash_to_point_test();
 52→    let result = PoseidonHashToPointImpl::hash_to_point(test.message.span(), test.salt.span());
 53→
 54→    let result_span = result.span();
 55→    let expected_span = test.expected.span();
 56→    assert_eq!(result_span.len(), expected_span.len());
 57→    let mut i: usize = 0;
 58→    while i != 512 {
 59→        assert_eq!(*result_span.at(i), *expected_span.at(i), "mismatch at index {}", i);
 60→        i += 1;
 61→    };
 62→}
