 64→#[test]
 65→fn test_packing_matches_rust() {
 66→    let test = load_packing_test();
 67→
 68→    // Test pack: Cairo pack should produce same felt252 values as Rust
 69→    let packed = pack_public_key(test.values.span());
 70→    let packed_span = packed.span();
 71→    let test_packed_span = test.packed.span();
 72→    assert_eq!(packed_span.len(), test_packed_span.len());
 73→    let mut i: usize = 0;
 74→    while i != packed_span.len() {
 75→        assert_eq!(*packed_span.at(i), *test_packed_span.at(i), "pack mismatch at slot {}", i);
 76→        i += 1;
 77→    }
 78→
 79→    // Test unpack: unpack Rust-generated packed values
 80→    let unpacked = unpack_public_key(test.packed.span());
 81→    let unpacked_span = unpacked.span();
 82→    let values_span = test.values.span();
 83→    assert_eq!(unpacked_span.len(), values_span.len());
 84→    i = 0;
 85→    while i != 512 {
 86→        assert_eq!(*unpacked_span.at(i), *values_span.at(i), "unpack mismatch at index {}", i);
 87→        i += 1;
 88→    };
