101→    let test = load_verify_test();
102→
103→    let pk = FalconPublicKey { h_ntt: test.pk_ntt };
104→    let sig = FalconSignature { s1: test.s1, salt: test.salt };
105→    let hint = FalconVerificationHint { mul_hint: test.mul_hint };
106→    let sig_with_hint = FalconSignatureWithHint { signature: sig, hint: hint };
107→
108→    let result = verify::<PoseidonHashToPoint>(@pk, sig_with_hint, test.message.span());
109→    assert!(result, "Falcon verify with Poseidon hash should pass");
110→}
111→
112→#[test]
113→fn test_verify_packed_matches_rust() {
114→    let test = load_verify_test();
115→
116→    let pk_packed = PackedPolynomial512Trait::from_coeffs(test.pk_ntt.span());
117→    let s1_packed = PackedPolynomial512Trait::from_coeffs(test.s1.span());
118→    let mul_hint_packed = PackedPolynomial512Trait::from_coeffs(test.mul_hint.span());
119→
120→    let sig = PackedFalconSignatureWithHint {
121→        signature: PackedFalconSignature { s1: s1_packed, salt: test.salt },
122→        hint: PackedFalconVerificationHint { mul_hint: mul_hint_packed },
123→    };
124→
125→    let result = verify_packed::<PoseidonHashToPoint>(@pk_packed, sig, test.message.span());
126→    assert!(result, "verify_packed with Poseidon hash should pass");
127→}
