107→#[starknet::contract(account)]
108→pub mod LegacyAccountMock {
109→    use core::num::traits::Zero;
110→    use openzeppelin_account::utils::is_valid_stark_signature;
111→    use starknet::SyscallResultTrait;
112→    use starknet::account::Call;
113→    use starknet::storage::{StoragePointerReadAccess, StoragePointerWriteAccess};
114→    use crate::mocks::observer::ObserverComponent;
115→    use crate::mocks::observer::ObserverComponent::InternalTrait as ObserverInternalTrait;
116→
117→    component!(path: ObserverComponent, storage: observer, event: ObserverEvent);
118→
119→    #[abi(embed_v0)]
120→    impl ObserverImpl = ObserverComponent::ObserverImpl<ContractState>;
121→
122→    #[event]
123→    #[derive(Drop, starknet::Event)]
124→    pub enum Event {
125→        #[flat]
126→        ObserverEvent: ObserverComponent::Event,
127→    }
128→
129→    #[storage]
130→    pub struct Storage {
131→        #[substorage(v0)]
132→        pub observer: ObserverComponent::Storage,
133→        pub public_key: felt252,
134→    }
135→
136→    #[constructor]
137→    fn constructor(ref self: ContractState, public_key: felt252) {
138→        self.public_key.write(public_key);
139→    }
140→
141→    #[abi(embed_v0)]
142→    pub impl LegacyAccountImpl of super::ILegacyAccount<ContractState> {
143→        fn __execute__(ref self: ContractState, calls: Array<Call>) {
144→            // Check sender
145→            let sender = starknet::get_caller_address();
146→            assert(sender.is_zero(), 'Account: invalid caller');
147→            // Check tx version
148→            let tx_version = starknet::get_tx_info().unbox().version;
149→            assert(tx_version == 0, 'Account: invalid tx version');
150→            // Validate transaction
151→            self.validate_transaction();
152→            // Execute calls
153→            for call in calls.span() {
154→                self.execute_single_call(call);
155→            }
156→            // Store event
157→            self.observer.store_call_info();
158→            // Emit event
159→            self.observer.emit_external_call_event();
160→        }
161→
162→        fn __validate__(self: @ContractState, calls: Array<Call>) -> felt252 {
163→            self.validate_transaction()
164→        }
165→
166→        fn is_valid_signature(
167→            self: @ContractState, hash: felt252, signature: Array<felt252>,
168→        ) -> felt252 {
169→            if self._is_valid_signature(hash, signature.span()) {
170→                starknet::VALIDATED
171→            } else {
172→                0
173→            }
174→        }
175→    }
176→
177→    #[generate_trait]
178→    pub impl InternalImpl of InternalTrait {
179→        fn validate_transaction(self: @ContractState) -> felt252 {
180→            let tx_info = starknet::get_tx_info().unbox();
181→            let tx_hash = tx_info.transaction_hash;
182→            let signature = tx_info.signature;
183→            assert(self._is_valid_signature(tx_hash, signature), 'Account: invalid signature');
184→            starknet::VALIDATED
185→        }
186→
187→        fn execute_single_call(self: @ContractState, call: @Call) {
188→            let Call { to, selector, calldata } = *call;
189→            starknet::syscalls::call_contract_syscall(to, selector, calldata).unwrap_syscall();
190→        }
191→
192→        fn _is_valid_signature(
193→            self: @ContractState, hash: felt252, signature: Span<felt252>,
194→        ) -> bool {
195→            let public_key = self.public_key.read();
196→            is_valid_stark_signature(hash, public_key, signature)
197→        }
198→    }
199→}
