22→pub fn get_accept_ownership_signature(
23→    account_address: ContractAddress, current_public_key: felt252, new_key_pair: StarkKeyPair,
24→) -> Span<felt252> {
25→    let msg_hash = PoseidonTrait::new()
26→        .update_with('StarkNet Message')
27→        .update_with('accept_ownership')
28→        .update_with(account_address)
29→        .update_with(current_public_key)
30→        .finalize();
31→    let (sig_r, sig_s) = new_key_pair.sign(msg_hash).unwrap();
32→    array![sig_r, sig_s].span()
33→}
