 1→use snforge_std::{ContractClass, ContractClassTrait, DeclareResult};
 2→use starknet::ContractAddress;
 3→use crate::panic_data_to_byte_array;
 4→
 5→/// Declares a contract with a `snforge_std::declare` call and unwraps the result.
 6→/// This function will skip declaration and just return the `ContractClass` if the contract is
 7→/// already declared (the result of `snforge_std::declare` call is of type
 8→/// `DeclareResult::AlreadyDeclared`)
 9→pub fn declare_class(contract_name: ByteArray) -> ContractClass {
10→    match snforge_std::declare(contract_name) {
11→        Result::Ok(declare_result) => match declare_result {
12→            DeclareResult::Success(contract_class) => contract_class,
13→            DeclareResult::AlreadyDeclared(contract_class) => contract_class,
14→        },
15→        Result::Err(panic_data) => panic!("{}", panic_data_to_byte_array(panic_data)),
16→    }
17→}
18→
19→/// Deploys an instance of a contract and unwraps the result.
20→pub fn deploy(contract_class: ContractClass, calldata: Array<felt252>) -> ContractAddress {
21→    match contract_class.deploy(@calldata) {
22→        Result::Ok((contract_address, _)) => contract_address,
23→        Result::Err(panic_data) => panic!("{}", panic_data_to_byte_array(panic_data)),
24→    }
25→}
26→
27→/// Deploys a contract at the given address and unwraps the result.
28→pub fn deploy_at(
29→    contract_class: ContractClass, target_address: ContractAddress, calldata: Array<felt252>,
30→) {
31→    match contract_class.deploy_at(@calldata, target_address) {
32→        Result::Ok(_) => (),
33→        Result::Err(panic_data) => panic!("{}", panic_data_to_byte_array(panic_data)),
34→    };
35→}
36→
37→/// Deploys a contract using the class hash from another already-deployed contract.
38→pub fn deploy_another_at(
39→    existing: ContractAddress, target_address: ContractAddress, calldata: Array<felt252>,
40→) {
41→    let class_hash = snforge_std::get_class_hash(existing);
42→    let contract_class = ContractClassTrait::new(class_hash);
43→    deploy_at(contract_class, target_address, calldata)
44→}
45→
46→/// Combines the declaration of a class and the deployment of a contract into one function call.
47→/// This function will skip declaration if the contract is
48→/// already declared (the result of `snforge_std::declare` call is of type
49→/// `DeclareResult::AlreadyDeclared`)
50→pub fn declare_and_deploy(contract_name: ByteArray, calldata: Array<felt252>) -> ContractAddress {
51→    let contract_class = declare_class(contract_name);
52→    deploy(contract_class, calldata)
53→}
54→
55→/// Combines the declaration of a class and the deployment of a contract at the given address
56→/// into one function call.
57→/// This function will skip declaration if the contract is
58→/// already declared (the result of `snforge_std::declare` call is of type
59→/// `DeclareResult::AlreadyDeclared`)
60→pub fn declare_and_deploy_at(
61→    contract_name: ByteArray, target_address: ContractAddress, calldata: Array<felt252>,
62→) {
63→    let contract_class = declare_class(contract_name);
64→    deploy_at(contract_class, target_address, calldata)
65→}
