  6→/// A wrapper around the `EventSpy` structure to allow treating the events as a queue.
  7→#[derive(Drop, Serde)]
  8→pub struct EventSpyQueue {
  9→    event_offset: usize,
 10→    event_spy: EventSpy,
 11→}
 12→
 13→/// Creates a new `EventSpyQueue` instance.
 14→pub fn spy_events() -> EventSpyQueue {
 15→    let event_spy = snforge_std::spy_events();
 16→    EventSpyQueue { event_offset: 0, event_spy }
 17→}
 18→
 19→#[generate_trait]
 20→pub impl EventSpyQueueImpl of EventSpyExt {
 21→    fn get_events(ref self: EventSpyQueue) -> Events {
 22→        let mut events = self.event_spy.get_events().events;
 23→
 24→        // Remove events that have already been consumed
 25→        for _ in 0..self.event_offset {
 26→            let _ = events.pop_front();
 27→        }
 28→
 29→        Events { events }
 30→    }
 31→
 32→    /// Ensures that `from_address` has emitted only the `expected_event` and no additional events.
 33→    fn assert_only_event<T, +starknet::Event<T>, +Drop<T>>(
 34→        ref self: EventSpyQueue, from_address: ContractAddress, expected_event: T,
 35→    ) {
 36→        self.assert_emitted_single(from_address, expected_event);
 37→        self.assert_no_events_left_from(from_address);
 38→    }
 39→
 40→    /// Ensures that `from_address` has emitted the `expected_event`.
 41→    /// This assertion increments the event offset which essentially
 42→    /// consumes the event in the first position of the offset. This means
 43→    /// that events must be asserted in the order that they're emitted.
 44→    fn assert_emitted_single<T, +starknet::Event<T>, +Drop<T>>(
 45→        ref self: EventSpyQueue, from_address: ContractAddress, expected_event: T,
 46→    ) {
 47→        self.assert_emitted(@array![(from_address, expected_event)]);
 48→        self.event_offset += 1;
 49→    }
 50→
 51→    /// Removes a single event from the queue. If the queue is empty, the function will panic.
 52→    fn drop_event(ref self: EventSpyQueue) {
 53→        self.drop_n_events(1);
 54→    }
 55→
 56→    /// Removes `number_to_drop` events from the queue. If the queue is empty, the function will
 57→    /// panic.
 58→    fn drop_n_events(ref self: EventSpyQueue, number_to_drop: u32) {
 59→        let events = self.get_events().events;
 60→        let len = events.len();
 61→        assert!(
 62→            len >= number_to_drop,
 63→            "Not enough events to drop. ${len} events, ${number_to_drop} to drop",
 64→        );
 65→        self.event_offset += number_to_drop;
 66→    }
 67→
 68→    /// Removes all events remaining on the queue. If the queue is empty already, the function will
 69→    /// do nothing.
 70→    fn drop_all_events(ref self: EventSpyQueue) {
 71→        let events = self.get_events().events;
 72→        self.event_offset += events.len();
 73→    }
 74→
 75→    /// Ensures that there are no events remaining on the queue.
 76→    fn assert_no_events_left(ref self: EventSpyQueue) {
 77→        let events = self.get_events().events;
 78→        assert!(events.len() == 0, "Events remaining on queue");
 79→    }
 80→
 81→    /// Ensures that there are no events emitted from the given address remaining on the queue.
 82→    fn assert_no_events_left_from(ref self: EventSpyQueue, from_address: ContractAddress) {
 83→        assert!(self.count_events_from(from_address) == 0, "Events remaining on queue");
 84→    }
 85→
 86→    /// Counts the number of remaining events emitted from the given address.
 87→    fn count_events_from(ref self: EventSpyQueue, from_address: ContractAddress) -> u32 {
 88→        let events = self.get_events().emitted_by(from_address).events;
 89→        events.len()
 90→    }
 91→}
