 93→/// The `ExpectedEvent` trait provides a convenient API for constructing
 94→/// expected events in tests.
 95→///
 96→/// This implementation is generated by the `#[generate_trait]` macro and offers
 97→/// three methods:
 98→///
 99→/// * `new()`: creates a fresh `Event` with empty `keys` and `data` arrays.
100→/// * `key(value)`: serializes the given value and appends it to the `keys` array.
101→/// * `data(value)`: serializes the given value and appends it to the `data` array.
102→///
103→/// By using these methods, you can construct events in a fluent style without
104→/// manually managing the `keys` and `data` arrays. For example, instead of:
105→///
106→/// ```cairo
107→/// let mut keys = array![];
108→/// keys.append_serde(selector!("Transfer")); // event selector
109→/// keys.append_serde(from);                  // key #1
110→/// keys.append_serde(to);                    // key #2
111→///
112→/// let mut data = array![];
113→/// data.append_serde(value);                 // non-key data
114→/// let expected = Event { keys, data };
115→///
116→/// spy.assert_emitted(
117→///     @array![(contract_address, expected)],
118→/// );
119→/// ```
120→///
121→/// you can now write:
122→///
123→/// ```cairo
124→/// let expected = ExpectedEvent::new()
125→///     .key(selector!("Transfer"))
126→///     .key(from)
127→///     .key(to)
128→///     .data(value);
129→/// spy.assert_emitted(
130→///     @array![(contract_address, expected)]
131→/// );
132→/// ```
133→///
134→/// NOTE: `key` and `data` accept any serializable value as input.
135→#[generate_trait]
136→pub impl ExpectedEvent of ExpectedEventTrait {
137→    /// Creates a new `Event` with empty `keys` and `data` arrays.
138→    fn new() -> Event {
139→        Event { keys: array![], data: array![] }
140→    }
141→
142→    /// Serializes the given value and appends it to the `keys` array.
143→    fn key<T, +Serde<T>, +Drop<T>>(self: Event, value: T) -> Event {
144→        let Event { mut keys, data } = self;
145→        value.serialize(ref keys);
146→        Event { keys, data }
147→    }
148→
149→    /// Serializes the given value and appends it to the `data` array.
150→    fn data<T, +Serde<T>, +Drop<T>>(self: Event, value: T) -> Event {
151→        let Event { keys, mut data } = self;
152→        value.serialize(ref data);
153→        Event { keys, data }
154→    }
155→}
