224→/// Allows to assert the expected events emission (or lack thereof),
225→/// in the scope of [`EventSpyQueue`] structure.
226→#[generate_trait]
227→impl EventSpyQueueAssertionsTraitImpl<
228→    T, impl TEvent: starknet::Event<T>, impl TDrop: Drop<T>,
229→> of EventSpyQueueAssertionsTrait<T> {
230→    fn assert_emitted(ref self: EventSpyQueue, events: @Array<(ContractAddress, T)>) {
231→        let mut i = 0;
232→        let received_events = self.get_events();
233→
234→        while i != events.len() {
235→            let (from, event) = events.at(i);
236→            let emitted = is_emitted(@received_events, from, event);
237→
238→            if !emitted {
239→                let from: felt252 = (*from).into();
240→                panic!("Event with matching data and keys was not emitted from {}", from);
241→            }
242→
243→            i += 1;
244→        };
245→    }
246→
247→    fn assert_not_emitted(ref self: EventSpyQueue, events: @Array<(ContractAddress, T)>) {
248→        let mut i = 0;
249→        let received_events = self.get_events();
250→
251→        while i != events.len() {
252→            let (from, event) = events.at(i);
253→            let emitted = is_emitted(@received_events, from, event);
254→
255→            if emitted {
256→                let from: felt252 = (*from).into();
257→                panic!("Event with matching data and keys was emitted from {}", from);
258→            }
259→
260→            i += 1;
261→        };
262→    }
263→}
