266→    self: @Events, expected_emitted_by: @ContractAddress, expected_event: @T,
267→) -> bool {
268→    let mut expected_keys = array![];
269→    let mut expected_data = array![];
270→    expected_event.append_keys_and_data(ref expected_keys, ref expected_data);
271→
272→    let mut i = 0;
273→    let mut is_emitted = false;
274→    while i != self.events.len() {
275→        let (from, event) = self.events.at(i);
276→
277→        if from == expected_emitted_by
278→            && event.keys == @expected_keys
279→            && event.data == @expected_data {
280→            is_emitted = true;
281→            break;
282→        }
283→
284→        i += 1;
285→    }
286→    return is_emitted;
287→}
