            mod = op.extra.get("modulus", self.modulus)
            return f"REDUCE_{a.bounds}_{mod}"
        elif op.op_type in ("DIV", "REM"):
            a, b = op.operands
            return f"DIVREM_{a.bounds}_{b.bounds}"
        return f"{op.op_type}_{id(op)}"

    def _gen_add_helper(self, op: Operation) -> str:
