182→/// Libfunc for dividing two non negative BoundedInts and getting the quotient and remainder.
183→#[derive(Default)]
184→pub struct BoundedIntDivRemLibfunc {}
185→impl NamedLibfunc for BoundedIntDivRemLibfunc {
186→    type Concrete = BoundedIntDivRemConcreteLibfunc;
187→
188→    const STR_ID: &'static str = "bounded_int_div_rem";
189→
190→    fn specialize_signature(
191→        &self,
192→        context: &dyn SignatureSpecializationContext,
193→        args: &[GenericArg],
194→    ) -> Result<LibfuncSignature, SpecializationError> {
195→        let (lhs, rhs) = args_as_two_types(args)?;
196→        let lhs_range = Range::from_type(context, lhs)?;
197→        let rhs_range = Range::from_type(context, rhs)?;
198→        // Supporting only division of a non-negative number by a positive number (non zero and non
199→        // negative).
200→        // TODO(orizi): Consider relaxing the constraint, and defining the
201→        // div_rem of negatives.
202→        require(!lhs_range.lower.is_negative() && !rhs_range.lower.is_negative())
203→            .ok_or(SpecializationError::UnsupportedGenericArg)?;
204→        // Making sure the algorithm is runnable.
205→        BoundedIntDivRemAlgorithm::try_new(&lhs_range, &rhs_range)
206→            .ok_or(SpecializationError::UnsupportedGenericArg)?;
207→        require(rhs_range.upper >= BigInt::from(2))
208→            .ok_or(SpecializationError::UnsupportedGenericArg)?;
209→        let quotient_min = lhs_range.lower / (&rhs_range.upper - 1);
210→        let quotient_max = (&lhs_range.upper - 1) / std::cmp::max(rhs_range.lower, BigInt::one());
211→        let range_check_type = context.get_concrete_type(RangeCheckType::id(), &[])?;
212→        Ok(LibfuncSignature::new_non_branch_ex(
213→            vec![
214→                ParamSignature::new(range_check_type.clone()).with_allow_add_const(),
215→                ParamSignature::new(lhs.clone()),
216→                ParamSignature::new(nonzero_ty(context, rhs)?),
217→            ],
218→            vec![
219→                OutputVarInfo::new_builtin(range_check_type),
220→                OutputVarInfo {
221→                    ty: bounded_int_ty(context, quotient_min, quotient_max)?,
222→                    ref_info: OutputVarReferenceInfo::SimpleDerefs,
223→                },
224→                OutputVarInfo {
225→                    ty: bounded_int_ty(context, 0.into(), rhs_range.upper - 2)?,
226→                    ref_info: OutputVarReferenceInfo::SimpleDerefs,
227→                },
228→            ],
229→            SierraApChange::Known { new_vars_only: false },
230→        ))
231→    }
232→
233→    fn specialize(
234→        &self,
235→        context: &dyn SpecializationContext,
236→        args: &[GenericArg],
237→    ) -> Result<Self::Concrete, SpecializationError> {
238→        let (lhs, rhs) = args_as_two_types(args)?;
239→        Ok(Self::Concrete {
240→            lhs: Range::from_type(context, lhs)?,
241→            rhs: Range::from_type(context, rhs)?,
242→            signature: self.specialize_signature(context, args)?,
243→        })
244→    }
245→}
