421→impl BoundedIntTrimConcreteLibfunc {
422→    fn new<const IS_MAX: bool>(
423→        context: &dyn SignatureSpecializationContext,
424→        args: &[GenericArg],
425→    ) -> Result<Self, SpecializationError> {
426→        let ty = args_as_single_type(args)?;
427→        let ty_info = context.get_type_info(ty)?;
428→        let range = Range::from_type_info(ty_info)?;
429→        let (res_ty, trimmed_value) = if IS_MAX {
430→            (
431→                bounded_int_ty(context, range.lower.clone(), range.upper.clone() - 2)?,
432→                range.upper - 1,
433→            )
434→        } else {
435→            (
436→                bounded_int_ty(context, range.lower.clone() + 1, range.upper.clone() - 1)?,
437→                range.lower,
438→            )
439→        };
440→        let ap_change = SierraApChange::Known { new_vars_only: trimmed_value.is_zero() };
441→        let signature = LibfuncSignature {
442→            param_signatures: vec![ParamSignature::new(ty.clone())],
443→            branch_signatures: vec![
444→                BranchSignature { vars: vec![], ap_change: ap_change.clone() },
445→                BranchSignature {
446→                    vars: vec![OutputVarInfo {
447→                        ty: res_ty,
448→                        ref_info: OutputVarReferenceInfo::SameAsParam { param_idx: 0 },
449→                    }],
450→                    ap_change,
451→                },
452→            ],
453→            fallthrough: Some(0),
454→        };
455→        Ok(Self { trimmed_value, signature })
456→    }
457→}
