 21→/// Builds instructions for bounded int operations.
 22→pub fn build(
 23→    libfunc: &BoundedIntConcreteLibfunc,
 24→    builder: CompiledInvocationBuilder<'_>,
 25→) -> Result<CompiledInvocation, InvocationError> {
 26→    match libfunc {
 27→        BoundedIntConcreteLibfunc::Add(_) => {
 28→            build_felt252_op_with_var(builder, Felt252BinaryOperator::Add)
 29→        }
 30→        BoundedIntConcreteLibfunc::Sub(_) => {
 31→            build_felt252_op_with_var(builder, Felt252BinaryOperator::Sub)
 32→        }
 33→        BoundedIntConcreteLibfunc::Mul(_) => {
 34→            build_felt252_op_with_var(builder, Felt252BinaryOperator::Mul)
 35→        }
 36→        BoundedIntConcreteLibfunc::DivRem(libfunc) => {
 37→            build_div_rem(builder, &libfunc.lhs, &libfunc.rhs)
 38→        }
 39→        BoundedIntConcreteLibfunc::Constrain(libfunc) => {
 40→            build_constrain(builder, &libfunc.boundary)
 41→        }
 42→        BoundedIntConcreteLibfunc::TrimMin(libfunc)
 43→        | BoundedIntConcreteLibfunc::TrimMax(libfunc) => {
 44→            build_trim(builder, &libfunc.trimmed_value)
 45→        }
 46→        BoundedIntConcreteLibfunc::IsZero(_) => build_is_zero(builder),
 47→        BoundedIntConcreteLibfunc::WrapNonZero(_) => build_identity(builder),
 48→    }
 49→}
