 51→/// Build div rem on bounded ints.
 52→/// Only supported cases are the cases where `BoundedIntDivRemAlgorithm::new` returns `Some`.
 53→pub fn build_div_rem(
 54→    builder: CompiledInvocationBuilder<'_>,
 55→    lhs: &Range,
 56→    rhs: &Range,
 57→) -> Result<CompiledInvocation, InvocationError> {
 58→    let [range_check, a, b] = builder.try_get_single_cells()?;
 59→
 60→    let alg = BoundedIntDivRemAlgorithm::try_new(lhs, rhs).unwrap();
 61→
 62→    let mut casm_builder = CasmBuilder::with_capacity(12, 2);
 63→    let rc_slack = match &alg {
 64→        BoundedIntDivRemAlgorithm::KnownSmallRhs => 2,
 65→        BoundedIntDivRemAlgorithm::KnownSmallQuotient { .. }
 66→        | BoundedIntDivRemAlgorithm::KnownSmallLhs { .. } => 3,
 67→    };
 68→    add_input_variables! {casm_builder,
 69→        buffer(rc_slack) range_check;
 70→        deref a;
 71→        deref b;
 72→    };
 73→    casm_build_extend! {casm_builder,
 74→        let orig_range_check = range_check;
 75→        tempvar r_plus_1;
 76→        tempvar b_minus_r_minus_1;
 77→    };
 78→
 79→    let (q_is_small, b_or_q_bound_rc_value) = match alg {
 80→        BoundedIntDivRemAlgorithm::KnownSmallRhs => (None, None),
 81→        BoundedIntDivRemAlgorithm::KnownSmallQuotient { .. } => {
 82→            (None, Some(casm_builder.alloc_var(false)))
 83→        }
 84→        BoundedIntDivRemAlgorithm::KnownSmallLhs { .. } => {
 85→            (Some(casm_builder.alloc_var(false)), Some(casm_builder.alloc_var(false)))
 86→        }
 87→    };
 88→    casm_build_extend! {casm_builder,
 89→        tempvar bq;
 90→        tempvar q;
 91→        tempvar r;
 92→        hint DivMod { lhs: a, rhs: b } into { quotient: q, remainder: r };
 93→    };
 94→
 95→    // The following assertion is added in all algorithms.
 96→    // For backward compatibility with the `u*_safe_divmod` libfuncs, we put it either here
 97→    // or below according to `alg`.
 98→    let range_check_q_after = matches!(alg, BoundedIntDivRemAlgorithm::KnownSmallRhs);
 99→    if !range_check_q_after {
100→        casm_build_extend!(casm_builder, assert q = *(range_check++););
101→    }
102→    casm_build_extend! {casm_builder,
103→        // Verify `0 <= r`.
104→        assert r = *(range_check++);
105→        // Verify `r < b` by constraining `0 <= b - (r + 1)`.
106→        const one = 1;
107→        assert r_plus_1 = r + one;
108→        assert b_minus_r_minus_1 = b - r_plus_1;
109→        assert b_minus_r_minus_1 = *(range_check++);
110→
111→    };
112→    if range_check_q_after {
113→        casm_build_extend!(casm_builder, assert q = *(range_check++););
114→    }
115→
116→    // Validating `(q + 1) * b <= prime` and therefore `q * b + r < q * b + b <= prime`.
117→    match alg {
118→        BoundedIntDivRemAlgorithm::KnownSmallRhs => {
119→            // For this case `q + 1 <= q_max + 1 <= 2**128` and `b < rhs.upper` therefore
120→            // `(q + 1) * b < 2**128 * rhs.upper <= prime`.
121→        }
122→        BoundedIntDivRemAlgorithm::KnownSmallQuotient { q_upper_bound } => {
123→            let b_or_q_bound_rc_value = b_or_q_bound_rc_value.unwrap();
124→            // For this case `(q + 1) <= q_bound`, and `b < rhs.upper <= 2**128` therefore
125→            // `(q + 1) * b < q_bound * 2**128 < prime`.
126→            casm_build_extend! {casm_builder,
127→                const u128_bound_minus_q_upper = (BigInt::one().shl(128) - q_upper_bound) as BigInt;
128→                assert b_or_q_bound_rc_value = q + u128_bound_minus_q_upper;
129→                assert b_or_q_bound_rc_value = *(range_check++);
130→            }
131→        }
132→        BoundedIntDivRemAlgorithm::KnownSmallLhs { lhs_upper_sqrt } => {
133→            let q_is_small = q_is_small.unwrap();
134→            let b_or_q_bound_rc_value = b_or_q_bound_rc_value.unwrap();
135→            casm_build_extend! {casm_builder,
136→                // Note that for an honest prover, `min{q, b} < root`, as otherwise
137→                // `lhs_upper > a >= q * b >= root ** 2` (and on the other hand,
138→                // by the definition of `root`: `root ** 2 >= lhs_upper`).
139→                // Therefore we require `min{q, b} < root`, which guarantees that:
140→                //   q * b + r < min{q, b} * max{q, b} + 2**128 <=
141→                //   (root - 1) * 2**128 + 2**128 <= root * 2**128 < prime.
142→                const limiter_bound = lhs_upper_sqrt.clone();
143→                hint TestLessThan {lhs: q, rhs: limiter_bound} into {dst: q_is_small};
144→                const u128_bound_minus_limiter_bound = (BigInt::one().shl(128) - lhs_upper_sqrt) as BigInt;
145→                jump QIsSmall if q_is_small != 0;
146→                // `q >= lhs_upper_sqrt`, so to verify `b < lhs_upper_sqrt` we assert
147→                // `2^128 - lhs_upper_sqrt + b` is in the range check bound.
148→                assert b_or_q_bound_rc_value = b + u128_bound_minus_limiter_bound;
149→                jump VerifyBQ;
150→            QIsSmall:
151→                // `q < lhs_upper_sqrt`, so to verify `q < lhs_upper_sqrt` we assert
152→                // `2^128 - lhs_upper_sqrt + q` is in the range check bound.
153→                assert b_or_q_bound_rc_value = q + u128_bound_minus_limiter_bound;
154→            VerifyBQ:
155→                // Now, b_or_q_bound_rc_value contains either `2^128 - lhs_upper_sqrt + q` or
156→                // `2^128 - lhs_upper_sqrt + b`. Verify this value is in [0, 2^128).
157→                assert b_or_q_bound_rc_value = *(range_check++);
158→            }
159→        }
160→    }
161→    casm_build_extend! {casm_builder,
162→        // Check that `a = q * b + r`.
163→        // We know that `q * b + r < prime` and thus there is no wraparound.
164→        assert bq = b * q;
165→        assert a = bq + r;
166→    }
167→    Ok(builder.build_from_casm_builder(
168→        casm_builder,
169→        [("Fallthrough", &[&[range_check], &[q], &[r]], None)],
170→        CostValidationInfo {
171→            builtin_infos: vec![BuiltinInfo {
172→                cost_token_ty: CostTokenType::RangeCheck,
173→                start: orig_range_check,
174→                end: range_check,
175→            }],
176→            extra_costs: None,
177→        },
178→    ))
179→}
