229→/// Build trim on bounded ints.
230→fn build_trim(
231→    builder: CompiledInvocationBuilder<'_>,
232→    trimmed_value: &BigInt,
233→) -> Result<CompiledInvocation, InvocationError> {
234→    let [value] = builder.try_get_single_cells()?;
235→    let mut casm_builder = CasmBuilder::with_capacity(2, 1);
236→    add_input_variables!(casm_builder, deref value; );
237→    casm_build_extend! {casm_builder,
238→        const trimmed_value = trimmed_value.clone();
239→        maybe_tempvar diff = value - trimmed_value;
240→        jump Target if diff != 0;
241→    };
242→    let target_statement_id = get_non_fallthrough_statement_id(&builder);
243→    Ok(builder.build_from_casm_builder(
244→        casm_builder,
245→        [("Fallthrough", &[], None), ("Target", &[&[value]], Some(target_statement_id))],
246→        Default::default(),
247→    ))
248→}
