 142→/// Returns a postcost value for a libfunc - the cost of step token.
 143→pub fn core_libfunc_cost(
 144→    libfunc: &CoreConcreteLibfunc,
 145→    info_provider: &dyn CostInfoProvider,
 146→) -> Vec<BranchCost> {
 147→    match libfunc {
 148→        FunctionCall(SignatureAndFunctionConcreteLibfunc { function, .. }) => {
 149→            vec![BranchCost::FunctionCost {
 150→                const_cost: ConstCost::steps(2),
 151→                function: FunctionCostInfo::new(function),
 152→                sign: BranchCostSign::Subtract,
 153→            }]
 154→        }
 155→        CouponCall(_) => vec![ConstCost::steps(2).into()],
 156→        Bool(libfunc) => match libfunc {
 157→            BoolConcreteLibfunc::And(_) => vec![ConstCost::steps(0).into()],
 158→            BoolConcreteLibfunc::Not(_) => vec![ConstCost::steps(1).into()],
 159→            BoolConcreteLibfunc::Xor(_) => vec![ConstCost::steps(1).into()],
 160→            BoolConcreteLibfunc::Or(_) => vec![ConstCost::steps(2).into()],
 161→            BoolConcreteLibfunc::ToFelt252(_) => vec![ConstCost::steps(0).into()],
 162→        },
 163→        Cast(libfunc) => match libfunc {
 164→            CastConcreteLibfunc::Downcast(libfunc) => {
 165→                if libfunc.from_range.is_full_felt252_range() {
 166→                    let success_extra_steps = if libfunc.to_range.lower.is_zero() { 0 } else { 1 }
 167→                        + if &libfunc.to_range.upper - 1 == u128::MAX.into() { 0 } else { 1 };
 168→                    let failure_extra_steps = if libfunc.to_range.upper.is_zero() { 0 } else { 1 };
 169→                    vec![
 170→                        ConstCost {
 171→                            steps: success_extra_steps + 3,
 172→                            holes: 0,
 173→                            range_checks: 2,
 174→                            range_checks96: 0,
 175→                        }
 176→                        .into(),
 177→                        ConstCost {
 178→                            steps: failure_extra_steps + 9,
 179→                            holes: 0,
 180→                            range_checks: 3,
 181→                            range_checks96: 0,
 182→                        }
 183→                        .into(),
 184→                    ]
 185→                } else {
 186→                    // Overflow tests are more expensive when asserting a value is above non-zero
 187→                    // value.
 188→                    let extra_below = if libfunc.to_range.lower.is_zero() { 0 } else { 1 };
 189→                    let extra_above = if libfunc.to_range.upper.is_zero() { 0 } else { 1 };
 190→                    match libfunc.cast_type() {
 191→                        CastType { overflow_above: false, overflow_below: false } => {
 192→                            vec![ConstCost::steps(0).into(), ConstCost::steps(0).into()]
 193→                        }
 194→                        CastType { overflow_above: true, overflow_below: false } => vec![
 195→                            (ConstCost::steps(3) + ConstCost::range_checks(1)).into(),
 196→                            (ConstCost::steps(3 + extra_above) + ConstCost::range_checks(1)).into(),
 197→                        ],
 198→                        CastType { overflow_above: false, overflow_below: true } => {
 199→                            vec![
 200→                                (ConstCost::steps(2 + extra_below) + ConstCost::range_checks(1))
 201→                                    .into(),
 202→                                (ConstCost::steps(4) + ConstCost::range_checks(1)).into(),
 203→                            ]
 204→                        }
 205→                        CastType { overflow_above: true, overflow_below: true } => {
 206→                            vec![
 207→                                (ConstCost::steps(4 + extra_below) + ConstCost::range_checks(2))
 208→                                    .into(),
 209→                                (ConstCost::steps(5) + ConstCost::range_checks(1)).into(),
 210→                            ]
 211→                        }
 212→                    }
 213→                }
 214→            }
 215→            CastConcreteLibfunc::Upcast(_) => vec![ConstCost::default().into()],
 216→        },
 217→        Ec(libfunc) => match libfunc {
 218→            EcConcreteLibfunc::IsZero(_) => {
 219→                vec![ConstCost::steps(1).into(), ConstCost::steps(1).into()]
 220→            }
 221→            EcConcreteLibfunc::Neg(_) | EcConcreteLibfunc::NegNz(_) => {
 222→                vec![ConstCost::default().into()]
 223→            }
 224→            EcConcreteLibfunc::StateAdd(_) => vec![ConstCost::steps(10).into()],
 225→            EcConcreteLibfunc::TryNew(_) => {
 226→                vec![ConstCost::steps(7).into(), ConstCost::steps(7).into()]
 227→            }
 228→            EcConcreteLibfunc::StateFinalize(_) => {
 229→                vec![ConstCost::steps(12).into(), ConstCost::steps(6).into()]
 230→            }
 231→            EcConcreteLibfunc::StateInit(_) => vec![ConstCost::steps(7).into()],
 232→            EcConcreteLibfunc::StateAddMul(_) => {
 233→                vec![BranchCost::Regular {
 234→                    const_cost: ConstCost::steps(5),
 235→                    pre_cost: PreCost::builtin(CostTokenType::EcOp),
 236→                }]
 237→            }
 238→            EcConcreteLibfunc::PointFromX(_) => vec![
 239→                (ConstCost::steps(14) + ConstCost::range_checks(3)).into(), // Success.
 240→                ConstCost::steps(9).into(),                                 // Failure.
 241→            ],
 242→            EcConcreteLibfunc::UnwrapPoint(_) => vec![ConstCost::default().into()],
 243→            EcConcreteLibfunc::Zero(_) => vec![ConstCost::default().into()],
 244→        },
 245→        Gas(libfunc) => match libfunc {
 246→            WithdrawGas(_) => vec![
 247→                BranchCost::WithdrawGas(WithdrawGasBranchInfo {
 248→                    success: true,
 249→                    with_builtin_costs: false,
 250→                }),
 251→                BranchCost::WithdrawGas(WithdrawGasBranchInfo {
 252→                    success: false,
 253→                    with_builtin_costs: false,
 254→                }),
 255→            ],
 256→            RedepositGas(_) => vec![BranchCost::RedepositGas],
 257→            GetAvailableGas(_) => vec![ConstCost::default().into()],
 258→            GetUnspentGas(_) => vec![
 259→                ConstCost::steps(
 260→                    BuiltinCostsType::cost_computation_steps(false, |_| 2).into_or_panic::<i32>()
 261→                        + 1,
 262→                )
 263→                .into(),
 264→            ],
 265→            BuiltinWithdrawGas(_) => {
 266→                vec![
 267→                    BranchCost::WithdrawGas(WithdrawGasBranchInfo {
 268→                        success: true,
 269→                        with_builtin_costs: true,
 270→                    }),
 271→                    BranchCost::WithdrawGas(WithdrawGasBranchInfo {
 272→                        success: false,
 273→                        with_builtin_costs: true,
 274→                    }),
 275→                ]
 276→            }
 277→            GetBuiltinCosts(_) => vec![ConstCost::steps(3).into()],
 278→        },
 279→        GasReserve(libfunc) => match libfunc {
 280→            GasReserveConcreteLibfunc::Create(_) => vec![
 281→                (ConstCost::steps(3) + ConstCost::range_checks(1)).into(),
 282→                (ConstCost::steps(5) + ConstCost::range_checks(1)).into(),
 283→            ],
 284→            GasReserveConcreteLibfunc::Utilize(_) => vec![ConstCost::steps(0).into()],
 285→        },
 286→        BranchAlign(_) => vec![BranchCost::BranchAlign],
 287→        Array(libfunc) => match libfunc {
 288→            ArrayConcreteLibfunc::New(_) => vec![ConstCost::steps(1).into()],
 289→            ArrayConcreteLibfunc::SpanFromTuple(_) => vec![ConstCost::steps(0).into()],
 290→            ArrayConcreteLibfunc::TupleFromSpan(_) => {
 291→                vec![ConstCost::steps(3).into(), ConstCost::steps(3).into()]
 292→            }
 293→            ArrayConcreteLibfunc::Append(libfunc) => {
 294→                vec![ConstCost::steps(info_provider.type_size(&libfunc.ty) as i32).into()]
 295→            }
 296→            ArrayConcreteLibfunc::PopFront(_)
 297→            | ArrayConcreteLibfunc::PopFrontConsume(_)
 298→            | ArrayConcreteLibfunc::SnapshotPopFront(_)
 299→            | ArrayConcreteLibfunc::SnapshotPopBack(_) => {
 300→                vec![ConstCost::steps(2).into(), ConstCost::steps(3).into()]
 301→            }
 302→            ArrayConcreteLibfunc::SnapshotMultiPopFront(_)
 303→            | ArrayConcreteLibfunc::SnapshotMultiPopBack(_) => {
 304→                vec![
 305→                    (ConstCost::steps(4) + ConstCost::range_checks(1)).into(),
 306→                    (ConstCost::steps(5) + ConstCost::range_checks(1)).into(),
 307→                ]
 308→            }
 309→            ArrayConcreteLibfunc::Get(libfunc) => {
 310→                if info_provider.type_size(&libfunc.ty) == 1 {
 311→                    vec![
 312→                        (ConstCost::steps(5) + ConstCost::range_checks(1)).into(),
 313→                        (ConstCost::steps(5) + ConstCost::range_checks(1)).into(),
 314→                    ]
 315→                } else {
 316→                    vec![
 317→                        (ConstCost::steps(6) + ConstCost::range_checks(1)).into(),
 318→                        (ConstCost::steps(6) + ConstCost::range_checks(1)).into(),
 319→                    ]
 320→                }
 321→            }
 322→            ArrayConcreteLibfunc::Slice(libfunc) => {
 323→                if info_provider.type_size(&libfunc.ty) == 1 {
 324→                    vec![
 325→                        (ConstCost::steps(5) + ConstCost::range_checks(1)).into(),
 326→                        (ConstCost::steps(7) + ConstCost::range_checks(1)).into(),
 327→                    ]
 328→                } else {
 329→                    vec![
 330→                        (ConstCost::steps(7) + ConstCost::range_checks(1)).into(),
 331→                        (ConstCost::steps(8) + ConstCost::range_checks(1)).into(),
 332→                    ]
 333→                }
 334→            }
 335→            ArrayConcreteLibfunc::Len(libfunc) => {
 336→                vec![
 337→                    ConstCost::steps(if info_provider.type_size(&libfunc.ty) == 1 { 0 } else { 1 })
 338→                        .into(),
 339→                ]
 340→            }
 341→        },
 342→        Uint8(libfunc) => uint_libfunc_cost(libfunc),
 343→        Uint16(libfunc) => uint_libfunc_cost(libfunc),
 344→        Uint32(libfunc) => uint_libfunc_cost(libfunc),
 345→        Uint64(libfunc) => uint_libfunc_cost(libfunc),
 346→        Uint128(libfunc) => u128_libfunc_cost(libfunc),
 347→        Uint256(libfunc) => u256_libfunc_cost(libfunc).into_iter().map(BranchCost::from).collect(),
 348→        Uint512(libfunc) => u512_libfunc_cost(libfunc).into_iter().map(BranchCost::from).collect(),
 349→        Sint8(libfunc) => sint_libfunc_cost(libfunc),
 350→        Sint16(libfunc) => sint_libfunc_cost(libfunc),
 351→        Sint32(libfunc) => sint_libfunc_cost(libfunc),
 352→        Sint64(libfunc) => sint_libfunc_cost(libfunc),
 353→        Sint128(libfunc) => s128_libfunc_cost(libfunc),
 354→        Felt252(libfunc) => {
 355→            felt252_libfunc_cost(libfunc).into_iter().map(BranchCost::from).collect()
 356→        }
 357→        Drop(_) | Dup(_) | ApTracking(_) | UnwrapNonZero(_) => {
 358→            vec![ConstCost::default().into()]
 359→        }
 360→        Box(libfunc) => match libfunc {
 361→            BoxConcreteLibfunc::Into(libfunc) => {
 362→                let n_steps =
 363→                    std::cmp::max(1, info_provider.type_size(&libfunc.ty).try_into().unwrap());
 364→                vec![ConstCost::steps(n_steps).into()]
 365→            }
 366→            BoxConcreteLibfunc::LocalInto(_) => vec![ConstCost::steps(2).into()],
 367→            BoxConcreteLibfunc::Unbox(_) | BoxConcreteLibfunc::ForwardSnapshot(_) => {
 368→                vec![ConstCost::default().into()]
 369→            }
 370→        },
 371→        Mem(libfunc) => match libfunc {
 372→            StoreTemp(libfunc) => {
 373→                vec![ConstCost::steps(info_provider.type_size(&libfunc.ty) as i32).into()]
 374→            }
 375→            StoreLocal(libfunc) => {
 376→                let size = info_provider.type_size(&libfunc.ty) as i32;
 377→                vec![(ConstCost::steps(size) + ConstCost::holes(-size)).into()]
 378→            }
 379→            AllocLocal(libfunc) => {
 380→                vec![ConstCost::holes(info_provider.type_size(&libfunc.ty) as i32).into()]
 381→            }
 382→            FinalizeLocals(_) => vec![ConstCost::steps(1).into()],
 383→            Rename(_) => vec![ConstCost::default().into()],
 384→        },
 385→        UnconditionalJump(_) => {
 386→            vec![ConstCost::steps(1).into()]
 387→        }
 388→        Enum(libfunc) => match libfunc {
 389→            EnumConcreteLibfunc::Init(_) => vec![ConstCost::default().into()],
 390→            EnumConcreteLibfunc::FromBoundedInt(libfunc) => match libfunc.n_variants {
 391→                1 | 2 => vec![ConstCost::default().into()],
 392→                _ => vec![ConstCost::steps(1).into()],
 393→            },
 394→            EnumConcreteLibfunc::Match(sig) | EnumConcreteLibfunc::SnapshotMatch(sig) => {
 395→                let n = sig.signature.branch_signatures.len();
 396→                match n {
 397→                    0 => vec![],
 398→                    1 => vec![ConstCost::default().into()],
 399→                    2 => vec![ConstCost::steps(1).into(); 2],
 400→                    _ => chain!(
 401→                        iter::once(ConstCost::steps(1).into()),
 402→                        itertools::repeat_n(ConstCost::steps(2).into(), n - 1)
 403→                    )
 404→                    .collect_vec(),
 405→                }
 406→            }
 407→            EnumConcreteLibfunc::BoxedMatch(EnumBoxedMatchConcreteLibfunc {
 408→                signature, ..
 409→            }) => {
 410→                // BoxedMatch needs to load the variant selector with a double-deref (1 step)
 411→                // plus the regular match cost - but only when branching is actually needed.
 412→                match signature.branch_signatures.len() {
 413→                    0 => vec![],
 414→                    1 => vec![ConstCost::default().into()],
 415→                    2 => vec![ConstCost::steps(2).into(); 2],
 416→                    n => chain!(
 417→                        iter::once(ConstCost::steps(2).into()),
 418→                        itertools::repeat_n(ConstCost::steps(3).into(), n - 1)
 419→                    )
 420→                    .collect_vec(),
 421→                }
 422→            }
 423→        },
 424→        Struct(
 425→            StructConcreteLibfunc::Construct(_)
 426→            | StructConcreteLibfunc::Deconstruct(_)
 427→            | StructConcreteLibfunc::SnapshotDeconstruct(_)
 428→            | StructConcreteLibfunc::BoxedDeconstruct(_),
 429→        ) => {
 430→            vec![ConstCost::default().into()]
 431→        }
 432→        Felt252Dict(libfunc) => match libfunc {
 433→            Felt252DictConcreteLibfunc::New(_) => {
 434→                vec![(ConstCost::steps(9) + SEGMENT_ARENA_ALLOCATION_COST).into()]
 435→            }
 436→            Felt252DictConcreteLibfunc::Squash(_) => {
 437→                // The `dict_squash` operation incurs a fixed cost of `DICT_SQUASH_CONST_COST`,
 438→                // plus an additional cost of `DICT_SQUASH_UNIQUE_KEY_COST` for each read or write
 439→                // access to the dictionary. However, the true cost of processing each unique key
 440→                // is `DICT_SQUASH_UNIQUE_KEY_COST`, while accessing an existing key incurs a lower
 441→                // cost of `DICT_SQUASH_REPEATED_ACCESS_COST`.
 442→                //
 443→                // To accurately reflect these costs, we charge `DICT_SQUASH_UNIQUE_KEY_COST`
 444→                // for each read or write access, and within the `dict_squash` operation an amount
 445→                // of `DICT_SQUASH_UNIQUE_KEY_COST - DICT_SQUASH_REPEATED_ACCESS_COST` is refunded
 446→                // for each subsequent access to an existing key.
 447→                vec![DICT_SQUASH_FIXED_COST.into()]
 448→            }
 449→        },
 450→        Felt252SquashedDict(_) => vec![ConstCost::default().into()],
 451→        Pedersen(libfunc) => match libfunc {
 452→            PedersenConcreteLibfunc::PedersenHash(_) => {
 453→                vec![BranchCost::Regular {
 454→                    const_cost: ConstCost::steps(2),
 455→                    pre_cost: PreCost::builtin(CostTokenType::Pedersen),
 456→                }]
 457→            }
 458→        },
 459→        Poseidon(libfunc) => match libfunc {
 460→            PoseidonConcreteLibfunc::HadesPermutation(_) => vec![BranchCost::Regular {
 461→                const_cost: ConstCost::steps(3),
 462→                pre_cost: PreCost::builtin(CostTokenType::Poseidon),
 463→            }],
 464→        },
 465→        Starknet(libfunc) => {
 466→            starknet_libfunc_cost_base(libfunc).into_iter().map(BranchCost::from).collect()
 467→        }
 468→        Nullable(libfunc) => match libfunc {
 469→            NullableConcreteLibfunc::Null(_)
 470→            | NullableConcreteLibfunc::NullableFromBox(_)
 471→            | NullableConcreteLibfunc::ForwardSnapshot(_) => vec![ConstCost::default().into()],
 472→            NullableConcreteLibfunc::MatchNullable(_) => {
 473→                vec![ConstCost::steps(1).into(), ConstCost::steps(1).into()]
 474→            }
 475→        },
 476→        Debug(_) => vec![ConstCost::steps(1).into()],
 477→        SnapshotTake(_) => vec![ConstCost::default().into()],
 478→        Felt252DictEntry(libfunc) => match libfunc {
 479→            Felt252DictEntryConcreteLibfunc::Get(_) => {
 480→                vec![(ConstCost::steps(1) + DICT_SQUASH_UNIQUE_KEY_COST).into()]
 481→            }
 482→            Felt252DictEntryConcreteLibfunc::Finalize(_) => vec![ConstCost::steps(1).into()],
 483→        },
 484→        Bytes31(libfunc) => match libfunc {
 485→            Bytes31ConcreteLibfunc::Const(_) | Bytes31ConcreteLibfunc::ToFelt252(_) => {
 486→                vec![ConstCost::default().into()]
 487→            }
 488→            Bytes31ConcreteLibfunc::TryFromFelt252(_) => vec![
 489→                (ConstCost { steps: 7, holes: 0, range_checks: 3, range_checks96: 0 }).into(),
 490→                (ConstCost { steps: 9, holes: 0, range_checks: 3, range_checks96: 0 }).into(),
 491→            ],
 492→        },
 493→        Const(libfunc) => match libfunc {
 494→            ConstConcreteLibfunc::AsBox(_) => vec![ConstCost::steps(3).into()],
 495→            ConstConcreteLibfunc::AsImmediate(_) => vec![ConstCost::steps(0).into()],
 496→        },
 497→        Coupon(libfunc) => match libfunc {
 498→            CouponConcreteLibfunc::Buy(libfunc) => {
 499→                vec![BranchCost::FunctionCost {
 500→                    const_cost: ConstCost::default(),
 501→                    function: FunctionCostInfo::new(&libfunc.function),
 502→                    sign: BranchCostSign::Subtract,
 503→                }]
 504→            }
 505→            CouponConcreteLibfunc::Refund(libfunc) => {
 506→                vec![BranchCost::FunctionCost {
 507→                    const_cost: ConstCost::default(),
 508→                    function: FunctionCostInfo::new(&libfunc.function),
 509→                    sign: BranchCostSign::Add,
 510→                }]
 511→            }
 512→        },
 513→        BoundedInt(libfunc) => match libfunc {
 514→            BoundedIntConcreteLibfunc::Add(_)
 515→            | BoundedIntConcreteLibfunc::Sub(_)
 516→            | BoundedIntConcreteLibfunc::Mul(_) => vec![ConstCost::steps(0).into()],
 517→            BoundedIntConcreteLibfunc::DivRem(libfunc) => {
 518→                vec![
 519→                    match BoundedIntDivRemAlgorithm::try_new(&libfunc.lhs, &libfunc.rhs).unwrap() {
 520→                        BoundedIntDivRemAlgorithm::KnownSmallRhs => {
 521→                            ConstCost { steps: 7, holes: 0, range_checks: 3, range_checks96: 0 }
 522→                        }
 523→                        BoundedIntDivRemAlgorithm::KnownSmallQuotient { .. } => {
 524→                            ConstCost { steps: 9, holes: 0, range_checks: 4, range_checks96: 0 }
 525→                        }
 526→                        BoundedIntDivRemAlgorithm::KnownSmallLhs { .. } => {
 527→                            ConstCost { steps: 11, holes: 0, range_checks: 4, range_checks96: 0 }
 528→                        }
 529→                    }
 530→                    .into(),
 531→                ]
 532→            }
 533→            BoundedIntConcreteLibfunc::Constrain(libfunc) => {
 534→                vec![
 535→                    (ConstCost {
 536→                        steps: 2 + if libfunc.boundary == BigInt::one().shl(128) { 0 } else { 1 },
 537→                        holes: 0,
 538→                        range_checks: 1,
 539→                        range_checks96: 0,
 540→                    })
 541→                    .into(),
 542→                    (ConstCost {
 543→                        steps: 3 + if libfunc.boundary.is_zero() { 0 } else { 1 },
 544→                        holes: 0,
 545→                        range_checks: 1,
 546→                        range_checks96: 0,
 547→                    })
 548→                    .into(),
 549→                ]
 550→            }
 551→            BoundedIntConcreteLibfunc::TrimMin(libfunc)
 552→            | BoundedIntConcreteLibfunc::TrimMax(libfunc) => {
 553→                let steps: BranchCost =
 554→                    ConstCost::steps(if libfunc.trimmed_value.is_zero() { 1 } else { 2 }).into();
 555→                vec![steps.clone(), steps]
 556→            }
 557→            BoundedIntConcreteLibfunc::IsZero(_) => {
 558→                vec![ConstCost::steps(1).into(), ConstCost::steps(1).into()]
 559→            }
 560→            BoundedIntConcreteLibfunc::WrapNonZero(_) => {
 561→                vec![ConstCost::steps(0).into()]
 562→            }
 563→        },
 564→        Circuit(libfunc) => match libfunc {
 565→            CircuitConcreteLibfunc::AddInput(_) => {
 566→                vec![ConstCost::steps(7).into(), ConstCost::steps(7).into()]
 567→            }
 568→            CircuitConcreteLibfunc::Eval(libfunc) => {
 569→                let info = info_provider.circuit_info(&libfunc.ty);
 570→
 571→                let instance_size: i32 = MOD_BUILTIN_INSTANCE_SIZE.into_or_panic();
 572→                let mut steps: i32 = 8 + instance_size;
 573→
 574→                if !info.add_offsets.is_empty() {
 575→                    steps += instance_size;
 576→                }
 577→
 578→                vec![
 579→                    // Failure.
 580→                    BranchCost::Regular {
 581→                        const_cost: ConstCost::steps(steps),
 582→                        pre_cost: PreCost(CostTokenMap::from_iter([
 583→                            (CostTokenType::AddMod, info.add_offsets.len().into_or_panic()),
 584→                            (CostTokenType::MulMod, info.mul_offsets.len().into_or_panic()),
 585→                        ])),
 586→                    },
 587→                    // Success.
 588→                    BranchCost::Regular {
 589→                        const_cost: ConstCost::steps(steps),
 590→                        pre_cost: PreCost(CostTokenMap::from_iter([
 591→                            (CostTokenType::AddMod, info.add_offsets.len().into_or_panic()),
 592→                            (CostTokenType::MulMod, info.mul_offsets.len().into_or_panic()),
 593→                        ])),
 594→                    },
 595→                ]
 596→            }
 597→            CircuitConcreteLibfunc::GetOutput(_) => {
 598→                vec![ConstCost::steps(5).into()]
 599→            }
 600→            CircuitConcreteLibfunc::TryIntoCircuitModulus(_) => {
 601→                vec![ConstCost::steps(6).into(), ConstCost::steps(7).into()]
 602→            }
 603→            CircuitConcreteLibfunc::GetDescriptor(_) => {
 604→                vec![ConstCost::steps(6).into()]
 605→            }
 606→            CircuitConcreteLibfunc::IntoU96Guarantee(_) => {
 607→                vec![ConstCost::steps(0).into()]
 608→            }
 609→            CircuitConcreteLibfunc::U96GuaranteeVerify(_) => {
 610→                vec![ConstCost { steps: 1, holes: 0, range_checks: 0, range_checks96: 1 }.into()]
 611→            }
 612→            CircuitConcreteLibfunc::U96LimbsLessThanGuaranteeVerify(_) => {
 613→                vec![ConstCost::steps(2).into(), ConstCost::steps(2).into()]
 614→            }
 615→            CircuitConcreteLibfunc::U96SingleLimbLessThanGuaranteeVerify(_) => {
 616→                vec![ConstCost::steps(0).into()]
 617→            }
 618→            CircuitConcreteLibfunc::InitCircuitData(libfunc) => {
 619→                let info = info_provider.circuit_info(&libfunc.ty);
 620→                vec![
 621→                    ConstCost {
 622→                        steps: 0,
 623→                        holes: 0,
 624→                        range_checks: 0,
 625→                        range_checks96: info.rc96_usage().into_or_panic(),
 626→                    }
 627→                    .into(),
 628→                ]
 629→            }
 630→            CircuitConcreteLibfunc::FailureGuaranteeVerify(_) => {
 631→                // The libfunc costs 1 MulMod instance (in addition to the cost below).
 632→                // However, in the failure case `eval_circuit` uses at least one MulMod gate less
 633→                // than it actually costs, so the MulMod is already paid for.
 634→                vec![ConstCost { steps: 32, holes: 0, range_checks: 0, range_checks96: 6 }.into()]
 635→            }
 636→        },
 637→        IntRange(libfunc) => match libfunc {
 638→            IntRangeConcreteLibfunc::TryNew(_) => {
 639→                vec![
 640→                    ConstCost { steps: 3, holes: 0, range_checks: 1, range_checks96: 0 }.into(),
 641→                    ConstCost { steps: 5, holes: 0, range_checks: 1, range_checks96: 0 }.into(),
 642→                ]
 643→            }
 644→            IntRangeConcreteLibfunc::PopFront(_) => {
 645→                vec![ConstCost::steps(2).into(), ConstCost::steps(2).into()]
 646→            }
 647→        },
 648→        Blake(
 649→            BlakeConcreteLibfunc::Blake2sCompress(_) | BlakeConcreteLibfunc::Blake2sFinalize(_),
 650→        ) => vec![BranchCost::Regular {
 651→            const_cost: ConstCost::steps(0),
 652→            pre_cost: PreCost::builtin(CostTokenType::Blake),
 653→        }],
 654→        Trace(_) => vec![ConstCost::steps(1).into()],
 655→        QM31(libfunc) => match libfunc {
 656→            QM31Concrete::Const(_) => vec![ConstCost::default().into()],
 657→            QM31Concrete::IsZero(_) => vec![ConstCost::steps(1).into(), ConstCost::steps(1).into()],
 658→            // TODO(orizi): Add qm31 token to gas cost.
 659→            QM31Concrete::BinaryOperation(_) => vec![ConstCost::steps(1).into()],
 660→            QM31Concrete::Pack(_) => vec![ConstCost::steps(6).into()],
 661→            QM31Concrete::Unpack(_) => {
 662→                vec![ConstCost { steps: 15, holes: 0, range_checks: 5, range_checks96: 0 }.into()]
 663→            }
 664→            QM31Concrete::FromM31(_) => vec![ConstCost::default().into()],
 665→        },
 666→        UnsafePanic(_) => vec![],
 667→        DummyFunctionCall(_) => vec![ConstCost::steps(2).into()],
 668→    }
 669→}
