 671→impl BranchCost {
 672→    /// Returns a postcost value for a libfunc's branch - the cost of step token.
 673→    pub fn postcost<Ops: CostOperations, InfoProvider: InvocationCostInfoProvider>(
 674→        &self,
 675→        ops: &mut Ops,
 676→        info_provider: &InfoProvider,
 677→    ) -> Ops::CostValueType
 678→    where
 679→        Ops::CostValueType: std::ops::Add<Ops::CostValueType, Output = Ops::CostValueType>
 680→            + std::ops::Sub<Ops::CostValueType, Output = Ops::CostValueType>
 681→            + std::ops::Neg<Output = Ops::CostValueType>
 682→            + HasZero,
 683→    {
 684→        match self {
 685→            BranchCost::Regular { const_cost, pre_cost: _ } => ops.const_cost(*const_cost),
 686→            BranchCost::FunctionCost { const_cost, function, sign } => {
 687→                let mut cost = ops.const_cost(*const_cost);
 688→                if let Some(func_cost) = ops.function_token_cost(function, CostTokenType::Const) {
 689→                    cost = cost + func_cost;
 690→                }
 691→                match sign {
 692→                    BranchCostSign::Add => {
 693→                        // The refund may be at most `cost`. It can be smaller if the refund
 694→                        // cannot be used later (e.g., if the next
 695→                        // statement is `return`).
 696→                        if let Some(refund_cost) = ops.statement_var_cost(CostTokenType::Const) {
 697→                            refund_cost - cost
 698→                        } else {
 699→                            -cost
 700→                        }
 701→                    }
 702→                    BranchCostSign::Subtract => cost,
 703→                }
 704→            }
 705→            BranchCost::BranchAlign => {
 706→                let ap_change = info_provider.ap_change_var_value();
 707→                let burnt_cost =
 708→                    ops.statement_var_cost(CostTokenType::Const).unwrap_or_else(HasZero::zero);
 709→                if ap_change == 0 {
 710→                    burnt_cost
 711→                } else {
 712→                    burnt_cost
 713→                        + ops.const_cost(ConstCost {
 714→                            steps: 1,
 715→                            holes: ap_change as i32,
 716→                            range_checks: 0,
 717→                            range_checks96: 0,
 718→                        })
 719→                }
 720→            }
 721→            BranchCost::WithdrawGas(info) => {
 722→                let total_cost = ops.const_cost(
 723→                    info.const_cost(|token_type| info_provider.token_usages(token_type)),
 724→                );
 725→                if info.success
 726→                    && let Some(var_value) = ops.statement_var_cost(CostTokenType::Const)
 727→                {
 728→                    total_cost - var_value
 729→                } else {
 730→                    total_cost
 731→                }
 732→            }
 733→            BranchCost::RedepositGas => {
 734→                let base = ops.const_cost(ConstCost::steps(
 735→                    BuiltinCostsType::cost_computation_steps(false, |token_type| {
 736→                        info_provider.token_usages(token_type)
 737→                    })
 738→                    .into_or_panic(),
 739→                ));
 740→                if let Some(var_value) = ops.statement_var_cost(CostTokenType::Const) {
 741→                    base + var_value
 742→                } else {
 743→                    base
 744→                }
 745→            }
 746→        }
 747→    }
 748→
 749→    /// Returns a precost value for a libfunc's branch - the cost of non-step tokens.
 750→    pub fn precost<Ops: CostOperations>(&self, ops: &mut Ops) -> CostTokenMap<Ops::CostValueType>
 751→    where
 752→        Ops::CostValueType: std::ops::Add<Ops::CostValueType, Output = Ops::CostValueType>
 753→            + std::ops::Sub<Ops::CostValueType, Output = Ops::CostValueType>
 754→            + std::ops::Neg<Output = Ops::CostValueType>
 755→            + HasZero
 756→            + Eq,
 757→    {
 758→        match self {
 759→            BranchCost::Regular { const_cost: _, pre_cost } => pre_cost
 760→                .0
 761→                .iter()
 762→                .map(|(token_type, val)| (*token_type, ops.cost_token(*val)))
 763→                .collect(),
 764→            BranchCost::FunctionCost { const_cost: _, function, sign } => {
 765→                let func_content_cost: CostTokenMap<_> = CostTokenType::iter_precost()
 766→                    .filter_map(|token| Some((*token, ops.function_token_cost(function, *token)?)))
 767→                    .collect();
 768→                match sign {
 769→                    BranchCostSign::Add => {
 770→                        // The refund may be at most `cost`. It can be smaller if the refund cannot
 771→                        // be used later (e.g., if the next statement is
 772→                        // `return`).
 773→                        precost_statement_vars_cost(ops)
 774→                            .collect::<CostTokenMap<_>>()
 775→                            .sub_collection(func_content_cost)
 776→                    }
 777→                    BranchCostSign::Subtract => func_content_cost,
 778→                }
 779→            }
 780→            BranchCost::BranchAlign | BranchCost::RedepositGas => {
 781→                precost_statement_vars_cost(ops).collect()
 782→            }
 783→            BranchCost::WithdrawGas(info) => {
 784→                if info.success {
 785→                    precost_statement_vars_cost(ops).map(|(k, v)| (k, -v)).collect()
 786→                } else {
 787→                    Default::default()
 788→                }
 789→            }
 790→        }
 791→    }
 792→}
 793→
 794→/// Returns the sum of statement variables for all the requested tokens.
 795→fn precost_statement_vars_cost<Ops: CostOperations>(
 796→    ops: &Ops,
 797→) -> impl Iterator<Item = (CostTokenType, Ops::CostValueType)> {
 798→    CostTokenType::iter_precost()
 799→        .filter_map(|token_type| Some((*token_type, ops.statement_var_cost(*token_type)?)))
 800→}
