 806→    match libfunc {
 807→        UintConcrete::Const(_) | UintConcrete::ToFelt252(_) | UintConcrete::WideMul(_) => {
 808→            vec![ConstCost::default().into()]
 809→        }
 810→        UintConcrete::Operation(libfunc) => match libfunc.operator {
 811→            IntOperator::OverflowingAdd => {
 812→                vec![
 813→                    (ConstCost { steps: 4, holes: 0, range_checks: 1, range_checks96: 0 }).into(),
 814→                    (ConstCost { steps: 5, holes: 0, range_checks: 1, range_checks96: 0 }).into(),
 815→                ]
 816→            }
 817→            IntOperator::OverflowingSub => {
 818→                vec![
 819→                    (ConstCost { steps: 3, holes: 0, range_checks: 1, range_checks96: 0 }).into(),
 820→                    (ConstCost { steps: 5, holes: 0, range_checks: 1, range_checks96: 0 }).into(),
 821→                ]
 822→            }
 823→        },
 824→        UintConcrete::SquareRoot(_) => {
 825→            vec![(ConstCost { steps: 9, holes: 0, range_checks: 4, range_checks96: 0 }).into()]
 826→        }
 827→        UintConcrete::Equal(_) => {
 828→            vec![ConstCost::steps(2).into(), ConstCost::steps(3).into()]
 829→        }
 830→        UintConcrete::FromFelt252(_) => {
 831→            vec![
 832→                (ConstCost { steps: 4, holes: 0, range_checks: 2, range_checks96: 0 }).into(),
 833→                (ConstCost { steps: 10, holes: 0, range_checks: 3, range_checks96: 0 }).into(),
 834→            ]
 835→        }
 836→        UintConcrete::IsZero(_) => vec![ConstCost::steps(1).into(), ConstCost::steps(1).into()],
 837→        UintConcrete::Divmod(_) => {
 838→            vec![BranchCost::from(ConstCost {
 839→                steps: 7,
 840→                holes: 0,
 841→                range_checks: 3,
 842→                range_checks96: 0,
 843→            })]
 844→        }
 845→        UintConcrete::Bitwise(_) => {
 846→            vec![BranchCost::Regular {
 847→                const_cost: ConstCost::steps(2),
 848→                pre_cost: PreCost::builtin(CostTokenType::Bitwise),
 849→            }]
