 60→/// Returns the ap change for a core libfunc.
 61→/// Unknown ap changes are represented as `ApChange::Unknown`.
 62→pub fn core_libfunc_ap_change<InfoProvider: InvocationApChangeInfoProvider>(
 63→    libfunc: &CoreConcreteLibfunc,
 64→    info_provider: &InfoProvider,
 65→) -> Vec<ApChange> {
 66→    match libfunc {
 67→        ApTracking(ApTrackingConcreteLibfunc::Revoke(_)) => {
 68→            vec![ApChange::Unknown]
 69→        }
 70→        ApTracking(ApTrackingConcreteLibfunc::Enable(_)) => {
 71→            vec![ApChange::EnableApTracking]
 72→        }
 73→        ApTracking(ApTrackingConcreteLibfunc::Disable(_)) => {
 74→            vec![ApChange::DisableApTracking]
 75→        }
 76→        Array(libfunc) => match libfunc {
 77→            ArrayConcreteLibfunc::New(_) => vec![ApChange::Known(1)],
 78→            ArrayConcreteLibfunc::SpanFromTuple(_) => vec![ApChange::Known(0)],
 79→            ArrayConcreteLibfunc::TupleFromSpan(_) => vec![ApChange::Known(2), ApChange::Known(2)],
 80→            ArrayConcreteLibfunc::Append(_) => vec![ApChange::Known(0)],
 81→            ArrayConcreteLibfunc::PopFront(_)
 82→            | ArrayConcreteLibfunc::PopFrontConsume(_)
 83→            | ArrayConcreteLibfunc::SnapshotPopFront(_)
 84→            | ArrayConcreteLibfunc::SnapshotPopBack(_) => {
 85→                vec![ApChange::Known(1), ApChange::Known(1)]
 86→            }
 87→            ArrayConcreteLibfunc::SnapshotMultiPopFront(_)
 88→            | ArrayConcreteLibfunc::SnapshotMultiPopBack(_) => {
 89→                vec![ApChange::Known(3), ApChange::Known(3)]
 90→            }
 91→            ArrayConcreteLibfunc::Get(libfunc) => {
 92→                if info_provider.type_size(&libfunc.ty) == 1 { [4, 3] } else { [5, 4] }
 93→                    .map(ApChange::Known)
 94→                    .to_vec()
 95→            }
 96→            ArrayConcreteLibfunc::Slice(libfunc) => {
 97→                if info_provider.type_size(&libfunc.ty) == 1 { [4, 5] } else { [6, 6] }
 98→                    .map(ApChange::Known)
 99→                    .to_vec()
100→            }
101→            ArrayConcreteLibfunc::Len(libfunc) => {
102→                vec![ApChange::Known(if info_provider.type_size(&libfunc.ty) == 1 { 0 } else { 1 })]
103→            }
104→        },
105→        BranchAlign(_) => vec![ApChange::FromMetadata],
106→        Bool(libfunc) => match libfunc {
107→            BoolConcreteLibfunc::And(_) => vec![ApChange::Known(0)],
108→            BoolConcreteLibfunc::Not(_) => vec![ApChange::Known(1)],
109→            BoolConcreteLibfunc::Xor(_) => vec![ApChange::Known(1)],
110→            BoolConcreteLibfunc::Or(_) => vec![ApChange::Known(2)],
111→            BoolConcreteLibfunc::ToFelt252(_) => vec![ApChange::Known(0)],
112→        },
113→        Box(libfunc) => match libfunc {
114→            BoxConcreteLibfunc::Into(_) => vec![ApChange::Known(1)],
115→            BoxConcreteLibfunc::LocalInto(_) => vec![ApChange::Known(2)],
116→            BoxConcreteLibfunc::Unbox(_) => vec![ApChange::Known(0)],
117→            BoxConcreteLibfunc::ForwardSnapshot(_) => vec![ApChange::Known(0)],
118→        },
119→        Cast(libfunc) => match libfunc {
120→            CastConcreteLibfunc::Downcast(libfunc) => {
121→                if libfunc.from_range.is_full_felt252_range() {
122→                    let success_extra_steps = if libfunc.to_range.lower.is_zero() { 0 } else { 1 }
123→                        + if &libfunc.to_range.upper - 1 == u128::MAX.into() { 0 } else { 1 };
124→                    let failure_extra_steps = if libfunc.to_range.upper.is_zero() { 0 } else { 1 };
125→                    vec![
126→                        ApChange::Known(success_extra_steps + 1),
127→                        ApChange::Known(failure_extra_steps + 6),
128→                    ]
129→                } else {
130→                    // Overflow tests are more expensive when asserting a value is above non-zero
131→                    // value.
132→                    let extra_below = if libfunc.to_range.lower.is_zero() { 0 } else { 1 };
133→                    let extra_above = if libfunc.to_range.upper.is_zero() { 0 } else { 1 };
134→                    match libfunc.cast_type() {
135→                        CastType { overflow_above: false, overflow_below: false } => {
136→                            vec![ApChange::Known(0), ApChange::Known(0)]
137→                        }
138→                        CastType { overflow_above: true, overflow_below: false } => {
139→                            vec![ApChange::Known(2), ApChange::Known(1 + extra_above)]
140→                        }
141→                        CastType { overflow_above: false, overflow_below: true } => {
142→                            vec![ApChange::Known(1 + extra_below), ApChange::Known(2)]
143→                        }
144→                        CastType { overflow_above: true, overflow_below: true } => {
145→                            vec![ApChange::Known(2 + extra_below), ApChange::Known(3)]
146→                        }
147→                    }
148→                }
149→            }
150→            CastConcreteLibfunc::Upcast(_) => vec![ApChange::Known(0)],
151→        },
152→        Ec(libfunc) => match libfunc {
153→            EcConcreteLibfunc::IsZero(_) => vec![ApChange::Known(0), ApChange::Known(0)],
154→            EcConcreteLibfunc::Neg(_) | EcConcreteLibfunc::NegNz(_) => vec![ApChange::Known(0)],
155→            EcConcreteLibfunc::StateAdd(_) => vec![ApChange::Known(9)],
156→            EcConcreteLibfunc::TryNew(_) => vec![ApChange::Known(6), ApChange::Known(6)],
157→            EcConcreteLibfunc::StateFinalize(_) => vec![ApChange::Known(11), ApChange::Known(3)],
158→            EcConcreteLibfunc::StateInit(_) => vec![ApChange::Known(7)],
159→            EcConcreteLibfunc::StateAddMul(_) => vec![ApChange::Known(0)],
160→            EcConcreteLibfunc::PointFromX(_) => vec![ApChange::Known(11), ApChange::Known(7)],
161→            EcConcreteLibfunc::UnwrapPoint(_) => vec![ApChange::Known(0)],
162→            EcConcreteLibfunc::Zero(_) => vec![ApChange::Known(0)],
163→        },
164→        Drop(_) | Dup(_) => vec![ApChange::Known(0)],
165→        Felt252(libfunc) => match libfunc {
166→            Felt252Concrete::Const(_) => {
167→                vec![ApChange::Known(0)]
168→            }
169→            Felt252Concrete::BinaryOperation(bin_op) => {
170→                let op = match bin_op {
171→                    Felt252BinaryOperationConcrete::WithVar(op) => op.operator,
172→                    Felt252BinaryOperationConcrete::WithConst(op) => op.operator,
173→                };
174→                vec![ApChange::Known(if op == Felt252BinaryOperator::Div { 1 } else { 0 })]
175→            }
176→            Felt252Concrete::IsZero(_) => vec![ApChange::Known(0), ApChange::Known(0)],
177→        },
178→        Felt252SquashedDict(_) => {
179→            vec![ApChange::Known(0)]
180→        }
181→        FunctionCall(libfunc) | CouponCall(libfunc) => {
182→            vec![ApChange::FunctionCall(libfunc.function.id.clone())]
183→        }
184→        Gas(libfunc) => match libfunc {
185→            GasConcreteLibfunc::WithdrawGas(_) => {
186→                let cost_computation_ap_change: usize =
187→                    BuiltinCostsType::cost_computation_steps(false, |token_type| {
188→                        info_provider.token_usages(token_type)
189→                    });
190→                if cost_computation_ap_change == 0 {
191→                    vec![ApChange::Known(2), ApChange::Known(2)]
192→                } else {
193→                    vec![
194→                        ApChange::Known(cost_computation_ap_change + 2),
195→                        ApChange::Known(cost_computation_ap_change + 3),
196→                    ]
197→                }
198→            }
199→            GasConcreteLibfunc::RedepositGas(_) => {
200→                vec![ApChange::Known(BuiltinCostsType::cost_computation_steps(
201→                    false,
202→                    |token_type| info_provider.token_usages(token_type),
203→                ))]
204→            }
205→            GasConcreteLibfunc::GetAvailableGas(_) => {
206→                vec![ApChange::Known(0)]
207→            }
208→            GasConcreteLibfunc::GetUnspentGas(_) => {
209→                vec![ApChange::Known(BuiltinCostsType::cost_computation_steps(false, |_| 2) + 1)]
210→            }
211→            GasConcreteLibfunc::BuiltinWithdrawGas(_) => {
212→                let cost_computation_ap_change: usize =
213→                    BuiltinCostsType::cost_computation_steps(true, |token_type| {
214→                        info_provider.token_usages(token_type)
215→                    });
216→                vec![
217→                    ApChange::Known(cost_computation_ap_change + 2),
218→                    ApChange::Known(cost_computation_ap_change + 3),
219→                ]
220→            }
221→            GasConcreteLibfunc::GetBuiltinCosts(_) => vec![ApChange::Known(3)],
222→        },
223→        GasReserve(libfunc) => match libfunc {
224→            GasReserveConcreteLibfunc::Create(_) => {
225→                vec![ApChange::Known(2), ApChange::Known(3)]
226→            }
227→            GasReserveConcreteLibfunc::Utilize(_) => vec![ApChange::Known(0)],
228→        },
229→        Uint8(libfunc) => uint_ap_change(libfunc),
230→        Uint16(libfunc) => uint_ap_change(libfunc),
231→        Uint32(libfunc) => uint_ap_change(libfunc),
232→        Uint64(libfunc) => uint_ap_change(libfunc),
233→        Uint128(libfunc) => match libfunc {
234→            Uint128Concrete::Operation(libfunc) => match libfunc.operator {
235→                IntOperator::OverflowingAdd | IntOperator::OverflowingSub => {
236→                    vec![ApChange::Known(2), ApChange::Known(3)]
237→                }
238→            },
239→            Uint128Concrete::Divmod(_) => vec![ApChange::Known(7)],
240→            Uint128Concrete::GuaranteeMul(_) => vec![ApChange::Known(2)],
241→            Uint128Concrete::MulGuaranteeVerify(_) => vec![ApChange::Known(15)],
242→            Uint128Concrete::Equal(_) => vec![ApChange::Known(1), ApChange::Known(1)],
243→            Uint128Concrete::SquareRoot(_) => vec![ApChange::Known(6)],
244→            Uint128Concrete::FromFelt252(_) => vec![ApChange::Known(1), ApChange::Known(6)],
245→            Uint128Concrete::Const(_) | Uint128Concrete::ToFelt252(_) => {
246→                vec![ApChange::Known(0)]
247→            }
248→            Uint128Concrete::IsZero(_) => vec![ApChange::Known(0), ApChange::Known(0)],
249→            Uint128Concrete::ByteReverse(_) => vec![ApChange::Known(16)],
