488→/// Returns the ap changes for u8/u16/u32/u64 libfuncs.
489→fn uint_ap_change<TUintTraits: UintTraits + IntMulTraits + IsZeroTraits>(
490→    libfunc: &UintConcrete<TUintTraits>,
491→) -> Vec<ApChange> {
492→    match libfunc {
493→        UintConcrete::Const(_) | UintConcrete::ToFelt252(_) => vec![ApChange::Known(0)],
494→        UintConcrete::Operation(libfunc) => match libfunc.operator {
495→            IntOperator::OverflowingAdd => {
496→                vec![ApChange::Known(3), ApChange::Known(3)]
497→            }
498→            IntOperator::OverflowingSub => {
499→                vec![ApChange::Known(2), ApChange::Known(3)]
500→            }
501→        },
502→        UintConcrete::SquareRoot(_) => vec![ApChange::Known(6)],
503→        UintConcrete::Equal(_) => vec![ApChange::Known(1), ApChange::Known(1)],
504→        UintConcrete::FromFelt252(_) => vec![ApChange::Known(2), ApChange::Known(7)],
505→        UintConcrete::IsZero(_) => vec![ApChange::Known(0), ApChange::Known(0)],
506→        UintConcrete::Divmod(_) => vec![ApChange::Known(5)],
507→        UintConcrete::WideMul(_) => vec![ApChange::Known(0)],
508→        UintConcrete::Bitwise(_) => vec![ApChange::Known(0)],
509→    }
510→}
