512→/// Returns the ap changes for s8/s16/s32/s64 libfuncs.
513→fn sint_ap_change<TSintTraits: SintTraits + IntMulTraits>(
514→    libfunc: &SintConcrete<TSintTraits>,
515→) -> Vec<ApChange> {
516→    match libfunc {
517→        SintConcrete::Const(_) | SintConcrete::ToFelt252(_) => vec![ApChange::Known(0)],
518→        SintConcrete::Equal(_) => vec![ApChange::Known(1), ApChange::Known(1)],
519→        SintConcrete::FromFelt252(_) => vec![ApChange::Known(3), ApChange::Known(7)],
520→        SintConcrete::WideMul(_) => vec![ApChange::Known(0)],
521→        SintConcrete::Operation(_) => {
522→            vec![ApChange::Known(4), ApChange::Known(4), ApChange::Known(4)]
523→        }
524→        SintConcrete::Diff(_) => vec![ApChange::Known(2), ApChange::Known(3)],
