 18→/// Builds instructions for Sierra cast operations.
 19→pub fn build(
 20→    libfunc: &CastConcreteLibfunc,
 21→    builder: CompiledInvocationBuilder<'_>,
 22→) -> Result<CompiledInvocation, InvocationError> {
 23→    match libfunc {
 24→        CastConcreteLibfunc::Downcast(libfunc) => build_downcast(builder, libfunc),
 25→        CastConcreteLibfunc::Upcast(_) => build_identity(builder),
 26→    }
 27→}
 28→
 29→/// Builds Casm instructions for [CastConcreteLibfunc::Downcast].
 30→pub fn build_downcast(
 31→    builder: CompiledInvocationBuilder<'_>,
 32→    libfunc: &DowncastConcreteLibfunc,
 33→) -> Result<CompiledInvocation, InvocationError> {
 34→    if libfunc.from_range.is_full_felt252_range() {
 35→        return build_felt252_range_reduction(builder, &libfunc.to_range, true);
 36→    }
 37→    let [range_check, value] = builder.try_get_single_cells()?;
 38→    let mut casm_builder = CasmBuilder::with_capacity(12, 4);
 39→    add_input_variables!(casm_builder,
 40→        buffer(1) range_check;
 41→        deref value;
 42→    );
 43→
 44→    // The casm code below assumes both types are at most 128 bits.
 45→    assert!(
 46→        libfunc.from_range.is_small_range() && libfunc.to_range.is_small_range(),
 47→        "Downcasting is not supported for types of size > 128 bits."
 48→    );
 49→
 50→    casm_build_extend!(casm_builder, let orig_range_check = range_check;);
 51→
 52→    match libfunc.cast_type() {
 53→        CastType { overflow_above: false, overflow_below: false } => {
 54→            return handle_downcast_no_overflow(builder);
 55→        }
 56→        CastType { overflow_above: true, overflow_below: false } => add_downcast_overflow_above(
 57→            &mut casm_builder,
 58→            value,
 59→            range_check,
 60→            &libfunc.to_range.upper,
 61→        ),
 62→        CastType { overflow_above: false, overflow_below: true } => add_downcast_overflow_below(
 63→            &mut casm_builder,
 64→            value,
 65→            range_check,
 66→            &libfunc.to_range.lower,
 67→        ),
 68→        CastType { overflow_above: true, overflow_below: true } => {
 69→            add_downcast_overflow_both(&mut casm_builder, value, range_check, &libfunc.to_range)
 70→        }
 71→    }
 72→
 73→    let target_statement_id = get_non_fallthrough_statement_id(&builder);
 74→    Ok(builder.build_from_casm_builder(
 75→        casm_builder,
 76→        [
 77→            ("Fallthrough", &[&[range_check], &[value]], None),
 78→            ("Failure", &[&[range_check]], Some(target_statement_id)),
 79→        ],
 80→        CostValidationInfo {
 81→            builtin_infos: vec![BuiltinInfo {
 82→                cost_token_ty: CostTokenType::RangeCheck,
 83→                start: orig_range_check,
 84→                end: range_check,
 85→            }],
 86→            extra_costs: None,
 87→        },
 88→    ))
 89→}
