 91→/// Builds Casm instructions for [CastConcreteLibfunc::Downcast] for a trivial case where no
 92→/// overflow is possible.
 93→fn handle_downcast_no_overflow(
 94→    builder: CompiledInvocationBuilder<'_>,
 95→) -> Result<CompiledInvocation, InvocationError> {
 96→    let [range_check, value] = builder.try_get_single_cells()?;
 97→    let success = vec![
 98→        ReferenceExpression::from_cell(range_check.clone()),
 99→        ReferenceExpression::from_cell(value.clone()),
100→    ];
101→    let unreachable_failure = vec![ReferenceExpression::from_cell(range_check.clone())];
102→    Ok(builder.build(
103→        vec![],
104→        vec![],
105→        [success.into_iter(), unreachable_failure.into_iter()].into_iter(),
106→    ))
107→}
