109→/// Adds instructions for downcasting where the value may only overflow above.
110→/// Note: The type of `value` must be unsigned.
111→fn add_downcast_overflow_above(
112→    casm_builder: &mut CasmBuilder,
113→    value: Var,
114→    range_check: Var,
115→    upper_bound: &BigInt,
116→) {
117→    casm_build_extend! {casm_builder,
118→        // Use a hint to guess whether the result is in range (is_valid=1) or overflows
119→        // (is_valid=0).
120→        // `value` is non-negative as it must be unsigned.
121→        tempvar is_valid;
122→        const value_limit_imm = upper_bound.clone();
123→        hint TestLessThan {lhs: value, rhs: value_limit_imm} into {dst: is_valid};
124→        jump Success if is_valid != 0;
125→    }
126→    // Validating we overflowed above.
127→    validate_ge(casm_builder, range_check, value, upper_bound);
128→    casm_build_extend!(casm_builder, jump Failure;);
129→
130→    casm_build_extend!(casm_builder, Success:);
131→    validate_lt(casm_builder, range_check, value, upper_bound);
132→}
133→
134→/// Adds instructions for downcasting where the value may only overflow below.
135→fn add_downcast_overflow_below(
136→    casm_builder: &mut CasmBuilder,
137→    value: Var,
138→    range_check: Var,
139→    lower_bound: &BigInt,
140→) {
141→    casm_build_extend! {casm_builder,
142→        const minus_lower_bound = -lower_bound;
143→        let canonical_value = value + minus_lower_bound;
144→        // Use a hint to guess whether the result is in range (is_valid=1) or overflows
145→        // (is_valid=0).
146→        tempvar is_valid;
147→        const rc_bound_imm = (BigInt::from(u128::MAX) + 1) as BigInt;
148→        hint TestLessThan {lhs: canonical_value, rhs: rc_bound_imm} into {dst: is_valid};
149→        jump Success if is_valid != 0;
150→        // Overflow below.
151→    }
152→    validate_lt(casm_builder, range_check, value, lower_bound);
153→    casm_build_extend!(casm_builder, jump Failure;);
154→
155→    casm_build_extend!(casm_builder, Success:);
156→    validate_ge(casm_builder, range_check, value, lower_bound);
157→}
