159→/// Adds instructions for downcasting where the value may both overflow and underflow.
160→fn add_downcast_overflow_both(
161→    casm_builder: &mut CasmBuilder,
162→    value: Var,
163→    range_check: Var,
164→    to_range: &Range,
165→) {
166→    casm_build_extend! {casm_builder,
167→        const minus_to_min_value = -to_range.lower.clone();
168→        let canonical_value = value + minus_to_min_value;
169→        // Use a hint to guess whether the result is in range (is_valid=1) or overflows
170→        // (is_valid=0).
171→        tempvar is_valid;
172→        const to_range_size = to_range.size();
173→        hint TestLessThan {lhs: canonical_value, rhs: to_range_size} into {dst: is_valid};
174→        jump Success if is_valid != 0;
175→        // Failure.
176→        const rc_bound_imm = (BigInt::from(u128::MAX) + 1) as BigInt;
177→        tempvar is_overflow_above;
178→        // If the `canonical_value` is negative (and therefore larger than 2**128) this is an overflow
179→        // below.
180→        hint TestLessThan {lhs: canonical_value, rhs: rc_bound_imm} into {dst: is_overflow_above};
181→        jump OverflowAbove if is_overflow_above != 0;
182→    }
183→    // Overflow below.
184→    let prev = casm_builder.curr_ap_change();
185→    validate_lt(casm_builder, range_check, value, &to_range.lower);
186→    if prev == casm_builder.curr_ap_change() {
187→        // `validate_ge` would have `ap_change=1` so we need to match it.
188→        casm_build_extend!(casm_builder, tempvar _x;);
189→    }
190→    casm_build_extend!(casm_builder, jump Failure;);
191→
192→    casm_build_extend!(casm_builder, OverflowAbove:);
193→    let prev = casm_builder.curr_ap_change();
194→    validate_ge(casm_builder, range_check, value, &to_range.upper);
195→    if prev == casm_builder.curr_ap_change() {
196→        // `validate_lt` would have `ap_change=1` so we need to match it.
197→        casm_build_extend!(casm_builder, tempvar _x;);
198→    }
199→    casm_build_extend!(casm_builder, jump Failure;);
200→
201→    casm_build_extend!(casm_builder, Success:);
202→    validate_ge(casm_builder, range_check, value, &to_range.lower);
203→    validate_lt(casm_builder, range_check, value, &to_range.upper);
