216→/// Validates that `value` is greater or equal to `bound`.
217→/// If `bound` is zero, only range checks without an additional calculation.
218→fn validate_ge(casm_builder: &mut CasmBuilder, range_check: Var, value: Var, bound: &BigInt) {
219→    casm_build_extend! {casm_builder,
220→        // value >= bound  <=>  value - bound >= 0.
221→        const bound = bound.clone();
222→        maybe_tempvar shifted_value = value - bound;
223→        assert shifted_value = *(range_check++);
224→    };
225→}
