 16→/// Builds a libfunc that tries to convert a numeric value in the felt252 range to `out_range`.
 17→///
 18→/// If `verify_optimal_range` is true, the function will fail for ranges larger than
 19→/// `prime % u128::MAX`.
 20→///
 21→/// Assumption: out_range.size() <= 2**128.
 22→///
 23→/// Note: The function doesn't generate optimal code in the range `prime % u128::MAX <=
 24→/// out_range.size() <= 2**128` since in such a case `K=1` can be used in `validate_under_limit`.
 25→pub fn build_felt252_range_reduction(
 26→    builder: CompiledInvocationBuilder<'_>,
 27→    out_range: &Range,
 28→    verify_optimal_range: bool,
 29→) -> Result<CompiledInvocation, InvocationError> {
 30→    let prime: BigInt = Felt252::prime().into();
 31→    if verify_optimal_range {
 32→        // `validate_under_limit` is better with `K == 1` for other range.
 33→        assert!(
 34→            out_range.size() < (&prime % u128::MAX),
 35→            "build_felt252_range_reduction is suboptimal for this range."
 36→        );
 37→    }
 38→    assert!(
 39→        out_range.is_small_range(),
 40→        "build_felt252_range_reduction only works for small target ranges."
 41→    );
 42→
 43→    let [range_check, value] = builder.try_get_single_cells()?;
 44→    let mut casm_builder = CasmBuilder::with_capacity(15, 2);
 45→    add_input_variables! {casm_builder,
 46→        buffer(0) range_check;
 47→        deref value;
 48→    };
 49→    casm_build_extend! {casm_builder,
 50→        let orig_range_check = range_check;
 51→        const range_size = out_range.size();
 52→        const minus_range_lower = -out_range.lower.clone();
 53→        const range_upper = out_range.upper.clone();
 54→        let canonical_value = value + minus_range_lower;
 55→        tempvar in_range;
 56→        hint TestLessThan {lhs: canonical_value, rhs: range_size} into {dst: in_range};
 57→        jump InRange if in_range != 0;
 58→        // OutOfRange:
 59→        // Using `maybe_tempvar` since `range_upper` may be 0.
 60→        maybe_tempvar validated_value = value - range_upper;
 61→    }
 62→
 63→    // Assert that `value - out_range.upper < prime - out_range.size()`.
 64→    let auxiliary_vars: [_; 5] = std::array::from_fn(|_| casm_builder.alloc_var(false));
 65→    // Note that if `verify_optimal_range = true` then `out_range.size() < prime % u128::MAX`
 66→    // and therefore `validate_under_limit<2>` is guaranteed to work:
 67→    //
 68→    // Let `x` be such that `out_range.size() == (prime % u128::MAX) - 1 - x`.
 69→    // We have:
 70→    //   * `0 <= x < prime % u128::MAX - 1`,
 71→    //   * `limit = prime - size = 2**251 + 17*2**192 + 1 - (2**123 + 17 * 2**64 + 1) + 1 + x`,
 72→    //   * `A = limit / (u128::MAX - 1) = 2**123 + 17*2**64`,
 73→    //   * `B = limit % (u128::MAX - 1) = 2**123 + 17*2**64 + 1 + x`.
 74→    // Since `x >= 0`, the `A <= B` condition is satisfied.
 75→    //
 76→    // The other cases would work if the inner assertions of `validate_under_limit` pass
 77→    // (the only such case currently used is the `felt252` to `i128` cast).
 78→    validate_under_limit::<2>(
 79→        &mut casm_builder,
 80→        &(prime - out_range.size()),
 81→        validated_value,
 82→        range_check,
 83→        &auxiliary_vars,
 84→    );
 85→    casm_build_extend! {casm_builder,
 86→    InRange:
 87→        // Using `maybe_tempvar` since `minus_range_lower` may be 0.
 88→        maybe_tempvar rc_val = value + minus_range_lower;
 89→        assert rc_val = *(range_check++);
 90→    }
 91→    let rc_size = u128_bound().clone();
 92→    // If the out range is exactly `rc_size` the previous addition to the buffer validated this
 93→    // case as well.
 94→    if out_range.size() < rc_size {
 95→        let upper_bound_fixer = rc_size - &out_range.upper;
 96→        casm_build_extend! {casm_builder,
 97→            const upper_bound_fixer = upper_bound_fixer;
 98→            // Using `maybe_tempvar` since `upper_bound_fixer` may be 0.
 99→            maybe_tempvar rc_val = value + upper_bound_fixer;
100→            assert rc_val = *(range_check++);
101→        }
102→    }
103→    let failure_handle_statement_id = get_non_fallthrough_statement_id(&builder);
104→    Ok(builder.build_from_casm_builder(
105→        casm_builder,
106→        [
107→            ("Fallthrough", &[&[range_check], &[value]], None),
108→            ("Done", &[&[range_check]], Some(failure_handle_statement_id)),
109→        ],
110→        CostValidationInfo {
111→            builtin_infos: vec![BuiltinInfo {
112→                cost_token_ty: CostTokenType::RangeCheck,
113→                start: orig_range_check,
114→                end: range_check,
115→            }],
116→            extra_costs: None,
117→        },
118→    ))
119→}
