340→impl Felt252Serde for Program {
341→    fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError> {
342→        // Type declarations.
343→        self.type_declarations.len().serialize(output)?;
344→        for (i, e) in self.type_declarations.iter().enumerate() {
345→            require(i as u64 == e.id.id)
346→                .ok_or(Felt252SerdeError::OutOfOrderTypeDeclarationsForSerialization)?;
347→            ConcreteTypeInfo {
348→                long_id: e.long_id.clone(),
349→                declared_type_info: e.declared_type_info.clone(),
350→            }
351→            .serialize(output)?;
352→        }
353→        // Libfunc declarations.
354→        self.libfunc_declarations.len().serialize(output)?;
355→        for (i, e) in self.libfunc_declarations.iter().enumerate() {
356→            require(i as u64 == e.id.id)
357→                .ok_or(Felt252SerdeError::OutOfOrderLibfuncDeclarationsForSerialization)?;
358→            e.long_id.serialize(output)?;
359→        }
360→        // Statements.
361→        Felt252Serde::serialize(&self.statements, output)?;
362→        // Function declarations.
363→        self.funcs.len().serialize(output)?;
364→        for (i, f) in self.funcs.iter().enumerate() {
365→            require(i as u64 == f.id.id)
366→                .ok_or(Felt252SerdeError::OutOfOrderUserFunctionDeclarationsForSerialization)?;
367→            f.signature.serialize(output)?;
368→            require(f.signature.param_types.len() == f.params.len())
369→                .ok_or(Felt252SerdeError::FunctionArgumentsMismatchInSerialization)?;
370→            for (param, ty) in f.params.iter().zip(f.signature.param_types.iter()) {
371→                require(param.ty == *ty)
372→                    .ok_or(Felt252SerdeError::FunctionArgumentsMismatchInSerialization)?;
373→                param.id.serialize(output)?;
374→            }
375→            f.entry_point.serialize(output)?;
376→        }
377→        Ok(())
378→    }
379→
380→    fn deserialize<'a, I: ExactSizeIterator<Item = &'a BigUint>>(
381→        input: &mut I,
382→    ) -> Result<Self, Felt252SerdeError> {
383→        // Type declarations.
384→        let size = usize::deserialize(input)?;
385→        let mut type_declarations = vec_with_bounded_capacity(size, input.len())?;
386→        for i in 0..size {
387→            let info = ConcreteTypeInfo::deserialize(input)?;
388→            type_declarations.push(TypeDeclaration {
389→                id: ConcreteTypeId::new(i as u64),
390→                long_id: info.long_id,
391→                declared_type_info: info.declared_type_info,
392→            });
393→        }
394→        // Libfunc declaration.
395→        let size = usize::deserialize(input)?;
396→        let mut libfunc_declarations = vec_with_bounded_capacity(size, input.len())?;
397→        for i in 0..size {
398→            let long_id = ConcreteLibfuncLongId::deserialize(input)?;
399→            libfunc_declarations
400→                .push(LibfuncDeclaration { id: ConcreteLibfuncId::new(i as u64), long_id });
401→        }
402→        // Statements.
403→        let statements = Felt252Serde::deserialize(input)?;
404→        // Function declaration.
405→        let size = usize::deserialize(input)?;
406→        let mut funcs = vec_with_bounded_capacity(size, input.len())?;
407→        for i in 0..size {
408→            let signature = FunctionSignature::deserialize(input)?;
409→            let params = signature
410→                .param_types
411→                .iter()
412→                .map(|ty| Ok(Param { id: VarId::deserialize(input)?, ty: ty.clone() }))
413→                .collect::<Result<Vec<_>, _>>()?;
414→            let entry_point = StatementIdx::deserialize(input)?;
415→            funcs.push(Function { id: FunctionId::new(i as u64), signature, params, entry_point });
416→        }
417→        Ok(Self { type_declarations, libfunc_declarations, statements, funcs })
418→    }
419→}
