575→/// Custom serialization for `GenericArg` to support negatives in `GenericArg::Value`.
576→impl Felt252Serde for GenericArg {
577→    fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError> {
578→        match self {
579→            GenericArg::UserType(id) => {
580→                0usize.serialize(output)?;
581→                id.serialize(output)
582→            }
583→            GenericArg::Type(id) => {
584→                1usize.serialize(output)?;
585→                id.serialize(output)
586→            }
587→            GenericArg::Value(value) if !value.is_negative() => {
588→                2usize.serialize(output)?;
589→                value.serialize(output)
590→            }
591→            GenericArg::UserFunc(id) => {
592→                3usize.serialize(output)?;
593→                id.serialize(output)
594→            }
595→            GenericArg::Libfunc(id) => {
596→                4usize.serialize(output)?;
597→                id.serialize(output)
598→            }
599→            GenericArg::Value(value) => {
600→                5usize.serialize(output)?;
601→                (-value).serialize(output)
602→            }
603→        }
604→    }
605→
606→    fn deserialize<'a, I: ExactSizeIterator<Item = &'a BigUint>>(
607→        input: &mut I,
608→    ) -> Result<Self, Felt252SerdeError> {
609→        match usize::deserialize(input)? {
610→            0 => Ok(Self::UserType(UserTypeId::deserialize(input)?)),
611→            1 => Ok(Self::Type(ConcreteTypeId::deserialize(input)?)),
612→            2 => Ok(Self::Value(BigInt::deserialize(input)?)),
