   116→    // verify that:
   117→    //   `a * b = 2**128 * res_high + res_low`.
   118→    let [range_check_ref, guarantee] = builder.try_get_refs()?;
   119→    let [range_check] = range_check_ref.try_unpack()?;
   120→    let [a, b, res_high, res_low] = guarantee.try_unpack()?;
   121→
   122→    let mut casm_builder = CasmBuilder::with_capacity(23, 0);
   123→    add_input_variables! {casm_builder,
   124→        buffer(8) range_check;
   125→        deref a;
   126→        deref b;
   127→        deref res_high;
   128→        deref res_low;
   129→    };
