   211→unsafe impl<'db> salsa::Update for SierraProgramWithDebug<'db> {
   212→    unsafe fn maybe_update(old_pointer: *mut Self, new_value: Self) -> bool {
   213→        let old_value = unsafe { &mut *old_pointer };
   214→        if old_value == &new_value {
