   242→                .unwrap_or_else(|| sierra_program.statements.len());
   243→            writeln!(f, "// {}:", func.id)?;
   244→            for param in &func.params {
   245→                writeln!(f, "//   {param}")?;
   246→            }
   247→            for i in start..end {
   248→                writeln!(f, "{}; // {i}", sierra_program.statements[i])?;
   249→                if let Some(loc) =
