   198→// Impls for generic ids.
   199→const SHORT_STRING_BOUND: usize = 31;
   200→/// A set of all the supported long generic ids.
   201→static SERDE_SUPPORTED_LONG_IDS: LazyLock<OrderedHashSet<&'static str>> = LazyLock::new(|| {
   202→    OrderedHashSet::from_iter([
   203→        StorageAddressFromBaseAndOffsetLibfunc::STR_ID,
   204→        ContractAddressTryFromFelt252Libfunc::STR_ID,
   205→        StorageBaseAddressFromFelt252Libfunc::STR_ID,
   206→        StorageAddressTryFromFelt252Trait::STR_ID,
   207→        Secp256GetPointFromXLibfunc::<Secp256k1>::STR_ID,
   208→        Secp256GetPointFromXLibfunc::<Secp256r1>::STR_ID,
   209→        CircuitFailureGuaranteeVerifyLibFunc::STR_ID,
   210→        U96LimbsLessThanGuaranteeVerifyLibfunc::STR_ID,
   211→        U96SingleLimbLessThanGuaranteeVerifyLibfunc::STR_ID,
   212→    ])
   213→});
   214→/// A mapping of all the long names when fixing them from the hashed keccak representation.
   215→static LONG_NAME_FIX: LazyLock<UnorderedHashMap<BigUint, &'static str>> = LazyLock::new(|| {
   216→    UnorderedHashMap::from_iter(
   217→        SERDE_SUPPORTED_LONG_IDS.iter().map(|name| (starknet_keccak(name.as_bytes()), *name)),
   218→    )
   219→});
