   181→/// Build constrain on bounded ints.
   182→fn build_constrain(
   183→    builder: CompiledInvocationBuilder<'_>,
   184→    boundary: &BigInt,
   185→) -> Result<CompiledInvocation, InvocationError> {
   186→    let [range_check, value] = builder.try_get_single_cells()?;
   187→
   188→    let mut casm_builder = CasmBuilder::with_capacity(6, 2);
   189→    add_input_variables! {casm_builder,
   190→        buffer(1) range_check;
   191→        deref value;
   192→    };
   193→    casm_build_extend! {casm_builder,
   194→        let orig_range_check = range_check;
   195→        const under_fixer = (BigInt::one().shl(128) - boundary) as BigInt;
   196→        const rc_bound_imm = BigInt::one().shl(128) as BigInt;
   197→        const minus_boundary = -boundary;
   198→        tempvar is_under;
   199→        let canonical_value = value + minus_boundary;
   200→        hint TestLessThanOrEqual {lhs: rc_bound_imm, rhs: canonical_value} into {dst: is_under};
   201→        jump Under if is_under != 0;
   202→    // Over:
   203→        maybe_tempvar shifted_value = canonical_value;
   204→        assert shifted_value = *(range_check++);
   205→        jump Over;
   206→    Under:
   207→        // value < boundary  <=>  value + (2**128 - boundary) < 2**128.
   208→        maybe_tempvar shifted_value = value + under_fixer;
   209→        assert shifted_value = *(range_check++);
   210→    };
   211→    let target_statement_id = get_non_fallthrough_statement_id(&builder);
   212→    Ok(builder.build_from_casm_builder(
   213→        casm_builder,
   214→        [
   215→            ("Fallthrough", &[&[range_check], &[value]], None),
   216→            ("Over", &[&[range_check], &[value]], Some(target_statement_id)),
   217→        ],
   218→        CostValidationInfo {
   219→            builtin_infos: vec![BuiltinInfo {
   220→                cost_token_ty: CostTokenType::RangeCheck,
   221→                start: orig_range_check,
   222→                end: range_check,
   223→            }],
   224→            extra_costs: None,
   225→        },
   226→    ))
   227→}
