    54→            zero_sized: false,
    55→            storable: true,
    56→            droppable: true,
    57→            duplicatable: true,
    58→        };
    59→
    60→        Ok(Self::Concrete { info: ty_info, range: Range::closed(min, max) })
    61→    }
