   369→                .ok_or(Felt252SerdeError::FunctionArgumentsMismatchInSerialization)?;
   370→            for (param, ty) in f.params.iter().zip(f.signature.param_types.iter()) {
   371→                require(param.ty == *ty)
   372→                    .ok_or(Felt252SerdeError::FunctionArgumentsMismatchInSerialization)?;
   373→                param.id.serialize(output)?;
   374→            }
   375→            f.entry_point.serialize(output)?;
