   434→impl Felt252Serde for ConcreteTypeInfo {
   435→    fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError> {
   436→        self.long_id.generic_id.serialize(output)?;
   437→        let len = self.long_id.generic_args.len() as u128;
   438→        let decl_ti_value: u64 = match &self.declared_type_info {
   439→            Some(info) => {
   440→                // The marker guarantees that the type info value is not 0.
   441→                TYPE_INFO_MARKER
   442→                    | (if info.storable { TYPE_STORABLE } else { 0 })
   443→                    | (if info.droppable { TYPE_DROPPABLE } else { 0 })
   444→                    | (if info.duplicatable { TYPE_DUPLICATABLE } else { 0 })
   445→                    | (if info.zero_sized { TYPE_ZERO_SIZED } else { 0 })
   446→            }
   447→            None => 0,
   448→        };
   449→        ((BigInt::from(len) + BigInt::from(decl_ti_value).shl(128)) as BigInt).serialize(output)?;
   450→        for arg in &self.long_id.generic_args {
   451→            arg.serialize(output)?;
   452→        }
   453→        Ok(())
   454→    }
