   402→        // Statements.
   403→        let statements = Felt252Serde::deserialize(input)?;
   404→        // Function declaration.
   405→        let size = usize::deserialize(input)?;
   406→        let mut funcs = vec_with_bounded_capacity(size, input.len())?;
   407→        for i in 0..size {
