   469→            generic_args.push(GenericArg::deserialize(input)?);
   470→        }
   471→        Ok(Self {
   472→            long_id: ConcreteTypeLongId { generic_id, generic_args },
   473→            declared_type_info: if decl_ti_value == 0 {
   474→                None
   475→            } else {
   476→                Some(DeclaredTypeInfo {
   477→                    storable: (decl_ti_value & TYPE_STORABLE) != 0,
   478→                    droppable: (decl_ti_value & TYPE_DROPPABLE) != 0,
   479→                    duplicatable: (decl_ti_value & TYPE_DUPLICATABLE) != 0,
   480→                    zero_sized: (decl_ti_value & TYPE_ZERO_SIZED) != 0,
   481→                })
   482→            },
   483→        })
   484→    }
