/// Approach B: u128s_from_felt252 + upcast to BoundedInt<0, u128_MAX>
/// This generates much smaller Sierra code.

use corelib_imports::bounded_int::{BoundedInt, DivRemHelper, bounded_int_div_rem, upcast};
use corelib_imports::integer::{U128sFromFelt252Result, u128s_from_felt252};

// Q = 12289 (Falcon prime)
type Zq = BoundedInt<0, 12288>;
type QConst = corelib_imports::bounded_int::UnitInt<12289>;

// SHIFT = 12289 * 2^118
const SHIFT: felt252 = 2305326338167692623066702044767191040;

type U128AsBounded = BoundedInt<0, 340282366920938463463374607431768211455>;

impl DivRem_U128_QConst of DivRemHelper<U128AsBounded, QConst> {
    type DivT = BoundedInt<0, 27689996494502275487295516920153650>;
    type RemT = Zq;
}

const NZ_Q: NonZero<QConst> = 12289;

#[inline(always)]
fn felt252_as_u128(x: felt252) -> u128 {
    match u128s_from_felt252(x) {
        U128sFromFelt252Result::Narrow(low) => low,
        U128sFromFelt252Result::Wide((_, low)) => low,
    }
}

#[starknet::interface]
trait IU128sApproach<TState> {
    fn reduce_32(
        self: @TState,
        x0: felt252, x1: felt252, x2: felt252, x3: felt252,
        x4: felt252, x5: felt252, x6: felt252, x7: felt252,
        x8: felt252, x9: felt252, x10: felt252, x11: felt252,
        x12: felt252, x13: felt252, x14: felt252, x15: felt252,
        x16: felt252, x17: felt252, x18: felt252, x19: felt252,
        x20: felt252, x21: felt252, x22: felt252, x23: felt252,
        x24: felt252, x25: felt252, x26: felt252, x27: felt252,
        x28: felt252, x29: felt252, x30: felt252, x31: felt252,
    ) -> (
        felt252, felt252, felt252, felt252,
        felt252, felt252, felt252, felt252,
        felt252, felt252, felt252, felt252,
        felt252, felt252, felt252, felt252,
        felt252, felt252, felt252, felt252,
        felt252, felt252, felt252, felt252,
        felt252, felt252, felt252, felt252,
        felt252, felt252, felt252, felt252,
    );
}

#[starknet::contract]
mod U128sContract {
    use super::{SHIFT, NZ_Q, bounded_int_div_rem, felt252_as_u128, U128AsBounded, upcast};

    #[storage]
    struct Storage {}

    #[inline(always)]
    fn reduce(x: felt252) -> felt252 {
        let shifted: U128AsBounded = upcast(felt252_as_u128(x + SHIFT));
        let (_, r) = bounded_int_div_rem(shifted, NZ_Q);
        upcast(r)
    }

    #[abi(embed_v0)]
    impl Impl of super::IU128sApproach<ContractState> {
        fn reduce_32(
            self: @ContractState,
            x0: felt252, x1: felt252, x2: felt252, x3: felt252,
            x4: felt252, x5: felt252, x6: felt252, x7: felt252,
            x8: felt252, x9: felt252, x10: felt252, x11: felt252,
