   206→/// Validates that `value` is smaller than `bound`.
   207→fn validate_lt(casm_builder: &mut CasmBuilder, range_check: Var, value: Var, bound: &BigInt) {
   208→    casm_build_extend! {casm_builder,
   209→        // value < bound  <=>  value + (2**128 - bound) < 2**128.
   210→        const pos_shift = (BigInt::from(u128::MAX) + 1 - bound) as BigInt;
   211→        maybe_tempvar shifted_value = value + pos_shift;
   212→        assert shifted_value = *(range_check++);
   213→    };
   214→}
