   308→/// Libfunc for constraining a BoundedInt<Min, Max> to one of two non-empty ranges: [Min, Boundary)
   309→/// or [Boundary, Max]. The libfunc is also applicable for standard types such as u* and i*.
   310→#[derive(Default)]
   311→pub struct BoundedIntConstrainLibfunc {}
   312→impl NamedLibfunc for BoundedIntConstrainLibfunc {
   313→    type Concrete = BoundedIntConstrainConcreteLibfunc;
   314→
   315→    const STR_ID: &'static str = "bounded_int_constrain";
   316→
   317→    fn specialize_signature(
   318→        &self,
   319→        context: &dyn SignatureSpecializationContext,
   320→        args: &[GenericArg],
   321→    ) -> Result<LibfuncSignature, SpecializationError> {
   322→        let (ty, boundary) = match args {
   323→            [GenericArg::Type(ty), GenericArg::Value(boundary)] => Ok((ty, boundary)),
   324→            [_, _] => Err(SpecializationError::UnsupportedGenericArg),
   325→            _ => Err(SpecializationError::WrongNumberOfGenericArgs),
   326→        }?;
   327→        let ty_info = context.get_type_info(ty)?;
   328→        let is_nz = ty_info.long_id.generic_id == NonZeroType::ID;
   329→        let range = if is_nz {
   330→            let inner_ty = args_as_single_type(&ty_info.long_id.generic_args)?;
   331→            Range::from_type(context, inner_ty)?
   332→        } else {
   333→            Range::from_type_info(ty_info)?
   334→        };
   335→        require(&range.lower < boundary && boundary < &range.upper)
   336→            .ok_or(SpecializationError::UnsupportedGenericArg)?;
   337→        let low_range = Range::half_open(range.lower, boundary.clone());
   338→        let high_range = Range::half_open(boundary.clone(), range.upper);
   339→        require(low_range.is_small_range() && high_range.is_small_range())
   340→            .ok_or(SpecializationError::UnsupportedGenericArg)?;
   341→        let range_check_type = context.get_concrete_type(RangeCheckType::id(), &[])?;
   342→        let branch_signature = |rng: Range| {
   343→            let inner_res_ty = bounded_int_ty(context, rng.lower, rng.upper - 1)?;
   344→            let res_ty = if is_nz { nonzero_ty(context, &inner_res_ty)? } else { inner_res_ty };
   345→            Ok(BranchSignature {
   346→                vars: vec![
   347→                    OutputVarInfo::new_builtin(range_check_type.clone()),
   348→                    OutputVarInfo {
   349→                        ty: res_ty,
   350→                        ref_info: OutputVarReferenceInfo::SameAsParam { param_idx: 1 },
   351→                    },
   352→                ],
   353→                ap_change: SierraApChange::Known { new_vars_only: false },
   354→            })
   355→        };
   356→        Ok(LibfuncSignature {
   357→            param_signatures: vec![
   358→                ParamSignature::new(range_check_type.clone()).with_allow_add_const(),
   359→                ParamSignature::new(ty.clone()),
   360→            ],
   361→            branch_signatures: vec![branch_signature(low_range)?, branch_signature(high_range)?],
   362→            fallthrough: Some(0),
   363→        })
   364→    }
   365→
   366→    fn specialize(
   367→        &self,
   368→        context: &dyn SpecializationContext,
   369→        args: &[GenericArg],
   370→    ) -> Result<Self::Concrete, SpecializationError> {
   371→        let boundary = match args {
   372→            [GenericArg::Type(_), GenericArg::Value(boundary)] => Ok(boundary.clone()),
   373→            [_, _] => Err(SpecializationError::UnsupportedGenericArg),
   374→            _ => Err(SpecializationError::WrongNumberOfGenericArgs),
   375→        }?;
   376→        Ok(Self::Concrete { boundary, signature: self.specialize_signature(context, args)? })
   377→    }
   378→}
