    44→/// Handles a u128 overflowing add operation.
    45→fn build_u128_overflowing_add(
    46→    builder: CompiledInvocationBuilder<'_>,
    47→) -> Result<CompiledInvocation, InvocationError> {
    48→    let failure_handle_statement_id = get_non_fallthrough_statement_id(&builder);
    49→    let [range_check, a, b] = builder.try_get_single_cells()?;
    50→    let mut casm_builder = CasmBuilder::with_capacity(6, 2);
    51→    add_input_variables! {casm_builder,
    52→        buffer(0) range_check;
    53→        deref a;
    54→        deref b;
    55→    };
    56→    casm_build_extend! {casm_builder,
    57→            let orig_range_check = range_check;
    58→            tempvar no_overflow;
    59→            tempvar a_plus_b = a + b;
    60→            const u128_limit = u128_bound().clone();
    61→            hint TestLessThan {lhs: a_plus_b, rhs: u128_limit} into {dst: no_overflow};
    62→            jump NoOverflow if no_overflow != 0;
    63→            // Overflow:
    64→            // Here we know that 2**128 <= a + b < 2 * 2**128 - 1.
    65→            tempvar wrapping_a_plus_b = a_plus_b - u128_limit;
    66→            assert wrapping_a_plus_b = *(range_check++);
    67→            jump Target;
    68→        NoOverflow:
    69→            assert a_plus_b = *(range_check++);
    70→    };
    71→    Ok(builder.build_from_casm_builder(
    72→        casm_builder,
    73→        [
    74→            ("Fallthrough", &[&[range_check], &[a_plus_b]], None),
    75→            ("Target", &[&[range_check], &[wrapping_a_plus_b]], Some(failure_handle_statement_id)),
    76→        ],
    77→        CostValidationInfo {
    78→            builtin_infos: vec![BuiltinInfo {
    79→                cost_token_ty: CostTokenType::RangeCheck,
    80→                start: orig_range_check,
    81→                end: range_check,
    82→            }],
    83→            extra_costs: None,
    84→        },
    85→    ))
    86→}
