   373→        temp = x;
   374→    }
   375→
   376→    // Now rather than swapping the high and low 64 bits, we split them into
   377→    // two 64-bit words.
   378→
   379→    // Right align the value.
   380→    casm_build_extend! {casm_builder,
   381→        // The inverse of `2**(8 + 16 + 32 + 64)` in the field.
   382→        const shift_inverse =
   383→            -BigInt::from_str_radix("800000000000011000000000000000000", 16).unwrap();
