   150→/// Helper to add code that validates that variable `value` is smaller than `limit`, with `K`
   151→/// constant for checking this bound. `auxiliary_vars` are the variables already allocated used for
   152→/// execution of the algorithm, requires different sizes for different `K`s, for 1 requires 4, for 2
   153→/// requires 5.
   154→///
   155→/// We show that a number is in the range [0, `limit`) by writing it as:
   156→///   A * x + y,
   157→/// where:
   158→///   * K = low positive number (the lower the better, here we support only 1 or 2).
   159→///   * max_x = 2**128 - K.
   160→///   * A = `limit` / max_x.
   161→///   * B = `limit` % max_x.
   162→///   * x is in the range [0, max_x],
   163→///   * y is in the range [0, B):
   164→///     * y is in the range [0, 2**128).
   165→///     * y + 2**128 - B is in the range [0, 2**128).
   166→///
   167→/// Note that the minimal possible value of the expression A * x + y is min_val = 0 (where x = y
   168→/// = 0), and the maximal value is obtained where x = max_x and y = B - 1:
   169→///   max_val = (A * max_x + B) - 1 = `limit` - 1.
   170→///
   171→/// As long as A <= B, every number in the range can be represented.
   172→/// We assert that the A and B generated by the provided `K` parameter fit the constraint.
   173→///
   174→/// If K == 1, the function falls through. If K == 2, the function jumps to a label named `Done`.
   175→pub fn validate_under_limit<const K: u8>(
   176→    casm_builder: &mut CasmBuilder,
   177→    limit: &BigInt,
   178→    value: Var,
   179→    range_check: Var,
   180→    auxiliary_vars: &[Var],
   181→) {
   182→    let a_imm = limit / (u128::MAX - (K - 1) as u128);
   183→    let b_imm = limit % (u128::MAX - (K - 1) as u128);
   184→    assert!(a_imm <= b_imm, "Must choose `K` such that `{a_imm} (`A`) <= {b_imm} (`B`)");
   185→    casm_build_extend! {casm_builder,
   186→        const a_imm = a_imm;
   187→        // 2**128 - B.
   188→        const b_imm_fix = (BigInt::from(u128::MAX) - b_imm + 1) as BigInt;
   189→        const u128_limit_minus_1 = u128::MAX;
   190→    }
   191→    match K {
   192→        1 => {
   193→            let (x, y, x_part, y_fixed) =
   194→                auxiliary_vars.iter().cloned().collect_tuple().expect("Wrong amount of vars.");
   195→            casm_build_extend! {casm_builder,
   196→                hint LinearSplit { value, scalar: a_imm, max_x: u128_limit_minus_1 } into { x, y };
   197→                assert x_part = x * a_imm;
   198→                assert value = x_part + y;
   199→                // x <= max_x = 2**128 - 1
   200→                assert x = *(range_check++);
   201→                // y < 2**128
   202→                assert y = *(range_check++);
   203→                // y + 2**128 - B < 2**128 ==> y < B
   204→                assert y_fixed = y + b_imm_fix;
   205→                assert y_fixed = *(range_check++);
   206→            };
   207→        }
   208→        2 => {
   209→            let (x, y, x_part, y_fixed, diff) =
   210→                auxiliary_vars.iter().cloned().collect_tuple().expect("Wrong amount of vars.");
   211→            casm_build_extend! {casm_builder,
   212→                const u128_limit_minus_2 = u128::MAX - 1;
   213→                hint LinearSplit { value, scalar: a_imm, max_x: u128_limit_minus_2 } into { x, y };
   214→                assert x_part = x * a_imm;
   215→                assert value = x_part + y;
   216→                // y < 2**128
   217→                assert y = *(range_check++);
   218→                // y + 2**128 - B < 2**128 ==> y < B
   219→                assert y_fixed = y + b_imm_fix;
   220→                assert y_fixed = *(range_check++);
   221→                // x < 2**128 && x != 2**128 - 1 ==> x < 2**128 - 1
   222→                assert x = *(range_check++);
   223→                assert diff = x - u128_limit_minus_1;
   224→                jump Done if diff != 0;
   225→                // As x cannot be 2**128 - 1, this is unreachable.
   226→                fail;
   227→            };
   228→        }
   229→        _ => unreachable!("Only K value of 1 or 2 are supported."),
   230→    }
   231→}
