   233→/// Helper function to generate code that computes a pointer after the end of the program code,
   234→/// at a given offset. This can be used for global constants.
   235→///
   236→/// Returns the instructions and the corresponding ap-change.
   237→pub fn get_pointer_after_program_code(offset: i32) -> (InstructionsWithRelocations, usize) {
   238→    let ctx = casm! {
   239→        // The relocation table will point the `call` to the end of the program, where there will
   240→        // be a `ret` instruction.
   241→        call rel 0;
   242→        // After calling an empty function, `[ap - 1]` contains the current `pc`.
   243→        // Using the relocations below, the immediate value (`offset`) will be changed so that it
   244→        // will compute a pointer to the second cell after the end of the program, which will
   245→        // contain the pointer to the builtin cost array.
   246→        [ap] = [ap - 1] + (offset), ap++;
   247→    };
   248→    let relocations = vec![
   249→        RelocationEntry { instruction_idx: 0, relocation: Relocation::EndOfProgram },
   250→        RelocationEntry { instruction_idx: 1, relocation: Relocation::EndOfProgram },
   251→    ];
   252→
   253→    (
   254→        InstructionsWithRelocations {
   255→            instructions: ctx.instructions,
   256→            relocations,
   257→            cost: ConstCost { steps: 3, ..Default::default() },
   258→        },
   259→        3,
   260→    )
   261→}
