   263→/// Builds a libfunc that tries to convert a felt252 to a type with values in the range
   264→/// `[0, 2**num_bits)`.
   265→/// Assumption: num_bits > 128.
   266→pub fn build_unsigned_try_from_felt252(
   267→    builder: CompiledInvocationBuilder<'_>,
   268→    num_bits: usize,
