   301→        casm_builder,
   302→        [
   303→            ("Fallthrough", &[&[range_check], &[value]], None),
   304→            ("Failure", &[&[range_check]], Some(failure_handle_statement_id)),
   305→        ],
   306→        CostValidationInfo {
   307→            builtin_infos: vec![BuiltinInfo {
   308→                cost_token_ty: CostTokenType::RangeCheck,
   309→                start: orig_range_check,
   310→                end: range_check,
   311→            }],
   312→            extra_costs: None,
