   131→        let orig_range_check = range_check;
   132→        tempvar a0;
   133→        tempvar a1;
   134→        const u64_limit = u64::MAX as u128 + 1;
   135→        // Break a into two 64-bit halves s.t. a = a1 * 2**64 + a0.
   136→        hint DivMod { lhs: a, rhs: u64_limit } into { quotient: a1, remainder: a0 };
   137→
