   139→        const u64_upper_fixer = u128::MAX - u64::MAX as u128;
   140→        tempvar fixed_a0 = a0 + u64_upper_fixer;
   141→        assert fixed_a0 = *(range_check++);
   142→        // Verify that a0, a1 are in [0, 2**128).
   143→        assert a0 = *(range_check++);
   144→        assert a1 = *(range_check++);
   145→        // Overall, we now have a0 in [0, 2**64) and a1 in [0, 2**128).
   146→
   147→        // Check the break: a = a1 * 2**64 + a0.
   148→        // Note: `a` is uint128, the assertion will fail if a1 >= 2**64.
   149→        tempvar a1_times_2_64 = a1 * u64_limit;
   150→        assert a = a1_times_2_64 + a0;
   151→
   152→
   153→        tempvar a0_b = a0 * b;
   154→        tempvar a1_b = a1 * b;
