   179→        assert a1_b0_bottom = *(range_check++);
   180→        assert partial_upper_word = *(range_check++);
   181→        // Check the break.
   182→        tempvar partial_upper_word_times_2_64 = partial_upper_word * u64_limit;
   183→        assert a1_b = partial_upper_word_times_2_64 + a1_b0_bottom;
