   193→        assert lower_uint128_with_carry = a0_b + shifted_a1_b0_bottom;
   194→        // Note that `lower_uint128_with_carry` is bounded by 193 bits, as `a0_b` is capped
   195→        // at 192 bits and `shifted_a1_b0_bottom` can contribute at most 1 additional bit,
   196→        // added to (the carry of) `lower_uint128_with_carry = a0_b + shifted_a1_b0_bottom`.
   197→        const u128_limit = u128_bound().clone();
