   206→        assert fixed_carry = *(range_check++);
   207→        assert carry = *(range_check++);
   208→        assert res_low = *(range_check++);
   209→        // Verify the outputted `res_low` and `carry` from the DivMod hint.
   210→        assert shifted_carry = carry * u128_limit;
   211→        assert lower_uint128_with_carry = shifted_carry + res_low;
