   213→        // with no wrap-around: `carry` was capped at 65 bits and then shifted 128 bits.
   214→        // `res_low` is range-checked for 128 bits. Overall, within 193 bits range.
   215→
   216→        // Upper uint128 word:
   217→        assert res_high = partial_upper_word + carry;
