   233→/// Handles casting a felt252 into u128.
   234→fn build_u128_from_felt252(
   235→    builder: CompiledInvocationBuilder<'_>,
   236→) -> Result<CompiledInvocation, InvocationError> {
   237→    let [range_check_expression, expr_value] = builder.try_get_refs()?;
   238→    let range_check = range_check_expression.try_unpack_single()?;
   239→    let value = expr_value.try_unpack_single()?;
   240→
   241→    let failure_handle_statement_id = get_non_fallthrough_statement_id(&builder);
   242→    let u128_bound = u128_bound(); // = 2**128.
   243→    // Represent the maximal possible value (PRIME - 1) as 2**128 * max_x + max_y.
   244→    let max_x: i128 = 10633823966279327296825105735305134080;
   245→    let max_y: i128 = 0;
   246→    let mut casm_builder = CasmBuilder::with_capacity(14, 4);
   247→    add_input_variables! {casm_builder,
   248→        buffer(3) range_check;
   249→        deref value;
   250→    };
   251→    casm_build_extend! {casm_builder,
   252→            let orig_range_check = range_check;
   253→            tempvar is_u128;
   254→            const u128_limit = u128_bound.clone();
   255→            hint TestLessThan { lhs: value, rhs: u128_limit } into { dst: is_u128 };
   256→            jump NoOverflow if is_u128 != 0;
   257→            // Allocating all values required so that `x` and `y` would be last.
   258→            tempvar x_2_128;
   259→            tempvar x_minus_max_x;
   260→            tempvar rced_value;
   261→            tempvar x;
   262→            tempvar y;
   263→            // Write value as 2**128 * x + y.
   264→            hint DivMod { lhs: value, rhs: u128_limit } into { quotient: x, remainder: y };
   265→            // Check x in [0, 2**128).
   266→            assert x = *(range_check++);
   267→            // Check y in [0, 2**128).
   268→            assert y = *(range_check++);
   269→            // Check that value = 2**128 * x + y (mod PRIME).
   270→            assert x_2_128 = x * u128_limit;
   271→            assert value = x_2_128 + y;
   272→            // Check that there is no overflow in the computation of 2**128 * x + y.
   273→            // Start by checking if x==max_x.
   274→            const minus_max_x = -max_x;
   275→            assert x_minus_max_x = x + minus_max_x;
   276→            jump XNotMaxX if x_minus_max_x != 0;
   277→            // If x == max_x, check that y <= max_y.
   278→            const le_max_y_fix = (u128_bound - max_y - 1) as BigInt;
   279→            assert rced_value = y + le_max_y_fix;
   280→            jump WriteRcedValue;
   281→        XNotMaxX:
   282→            // If x != max_x, check that x < max_x.
   283→            const lt_max_x_fix = (u128_bound - max_x) as BigInt;
   284→            assert rced_value = x + lt_max_x_fix;
   285→        WriteRcedValue:
   286→            // In both cases, range-check the calculated value.
   287→            assert rced_value = *(range_check++);
   288→            // If x != 0, jump to the end.
   289→            jump FailureHandle if x != 0;
   290→            // Otherwise, fail. As `x` must be non-zero in the overflow case, this is unreachable.
   291→            fail;
   292→        NoOverflow:
   293→            assert value = *(range_check++);
   294→    };
   295→    Ok(builder.build_from_casm_builder(
   296→        casm_builder,
   297→        [
   298→            ("Fallthrough", &[&[range_check], &[value]], None),
   299→            ("FailureHandle", &[&[range_check], &[x], &[y]], Some(failure_handle_statement_id)),
   300→        ],
   301→        CostValidationInfo {
   302→            builtin_infos: vec![BuiltinInfo {
   303→                cost_token_ty: CostTokenType::RangeCheck,
   304→                start: orig_range_check,
   305→                end: range_check,
   306→            }],
   307→            extra_costs: None,
   308→        },
   309→    ))
   310→}
