   421→/// Helper struct to serialize and deserialize a `ConcreteTypeLongId` and its optional
   422→/// `DeclaredTypeInfo`.
   423→struct ConcreteTypeInfo {
   424→    long_id: ConcreteTypeLongId,
   425→    declared_type_info: Option<DeclaredTypeInfo>,
   426→}
   427→
   428→const TYPE_INFO_MARKER: u64 = 0x8000000000000000;
   429→const TYPE_STORABLE: u64 = 0b0001;
   430→const TYPE_DROPPABLE: u64 = 0b0010;
   431→const TYPE_DUPLICATABLE: u64 = 0b0100;
   432→const TYPE_ZERO_SIZED: u64 = 0b1000;
   433→
   434→impl Felt252Serde for ConcreteTypeInfo {
   435→    fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError> {
   436→        self.long_id.generic_id.serialize(output)?;
   437→        let len = self.long_id.generic_args.len() as u128;
   438→        let decl_ti_value: u64 = match &self.declared_type_info {
   439→            Some(info) => {
   440→                // The marker guarantees that the type info value is not 0.
   441→                TYPE_INFO_MARKER
   442→                    | (if info.storable { TYPE_STORABLE } else { 0 })
   443→                    | (if info.droppable { TYPE_DROPPABLE } else { 0 })
   444→                    | (if info.duplicatable { TYPE_DUPLICATABLE } else { 0 })
   445→                    | (if info.zero_sized { TYPE_ZERO_SIZED } else { 0 })
   446→            }
   447→            None => 0,
   448→        };
   449→        ((BigInt::from(len) + BigInt::from(decl_ti_value).shl(128)) as BigInt).serialize(output)?;
   450→        for arg in &self.long_id.generic_args {
   451→            arg.serialize(output)?;
   452→        }
   453→        Ok(())
   454→    }
   455→
   456→    fn deserialize<'a, I: ExactSizeIterator<Item = &'a BigUint>>(
   457→        input: &mut I,
   458→    ) -> Result<Self, Felt252SerdeError> {
   459→        let generic_id = GenericTypeId::deserialize(input)?;
   460→        let len_and_decl_ti_value = BigInt::deserialize(input)?;
   461→        let len = (len_and_decl_ti_value.clone() & BigInt::from(u128::MAX))
   462→            .to_usize()
   463→            .ok_or(Felt252SerdeError::InvalidInputForDeserialization)?;
   464→        let decl_ti_value = (len_and_decl_ti_value.shr(128) as BigInt)
   465→            .to_u64()
   466→            .ok_or(Felt252SerdeError::InvalidInputForDeserialization)?;
   467→        let mut generic_args = vec_with_bounded_capacity(len, input.len())?;
   468→        for _ in 0..len {
   469→            generic_args.push(GenericArg::deserialize(input)?);
   470→        }
   471→        Ok(Self {
   472→            long_id: ConcreteTypeLongId { generic_id, generic_args },
   473→            declared_type_info: if decl_ti_value == 0 {
   474→                None
   475→            } else {
   476→                Some(DeclaredTypeInfo {
   477→                    storable: (decl_ti_value & TYPE_STORABLE) != 0,
   478→                    droppable: (decl_ti_value & TYPE_DROPPABLE) != 0,
   479→                    duplicatable: (decl_ti_value & TYPE_DUPLICATABLE) != 0,
   480→                    zero_sized: (decl_ti_value & TYPE_ZERO_SIZED) != 0,
   481→                })
   482→            },
   483→        })
   484→    }
   485→}
