   258→/// The algorithm to use for division and remainder of bounded integers.
   259→pub enum BoundedIntDivRemAlgorithm {
   260→    /// The rhs is small enough to be multiplied by `2**128` without wraparound.
   261→    KnownSmallRhs,
   262→    /// The quotient is small enough to be multiplied by `2**128` without wraparound.
   263→    KnownSmallQuotient { q_upper_bound: BigInt },
   264→    /// The lhs is small enough so that its square root plus 1 can be multiplied by `2**128`
   265→    /// without wraparound.
   266→    /// `lhs_upper_sqrt` is the square root of the upper bound of the lhs, rounded up.
   267→    KnownSmallLhs { lhs_upper_sqrt: BigInt },
   268→}
   269→impl BoundedIntDivRemAlgorithm {
   270→    /// Returns the algorithm to use for division and remainder of bounded integers.
   271→    /// Fails if the div_rem of the ranges is not supported yet.
   272→    ///
   273→    /// Assumption: `lhs` is non-negative and `rhs` is positive.
   274→    pub fn try_new(lhs: &Range, rhs: &Range) -> Option<Self> {
   275→        let prime = Felt252::prime().to_bigint().unwrap();
   276→        // Note that `rhs.lower` may be 0 - but since it is a non-zero type, it is guaranteed to be
   277→        // at least 1.
   278→        let q_max = (&lhs.upper - 1) / std::cmp::max(&rhs.lower, &BigInt::one());
   279→        let u128_limit = BigInt::one().shl(128);
   280→        // `q` is range checked in all algorithm variants, so `q_max` must be smaller than `2**128`.
   281→        require(q_max < u128_limit)?;
   282→        // `r` is range checked in all algorithm variants, so `rhs.upper` must be at most
   283→        // `2**128 + 1`.
   284→        require(rhs.upper <= &u128_limit + 1)?;
   285→        if &rhs.upper * &u128_limit < prime {
   286→            return Some(Self::KnownSmallRhs);
   287→        }
   288→        let q_upper_bound = q_max + 1;
   289→        if &q_upper_bound * &u128_limit < prime {
   290→            return Some(Self::KnownSmallQuotient { q_upper_bound });
   291→        }
   292→        let mut lhs_upper_sqrt = lhs.upper.sqrt();
   293→        // Round lhs_upper_sqrt up.
   294→        if lhs_upper_sqrt.pow(2) != lhs.upper {
   295→            lhs_upper_sqrt += 1;
   296→        }
   297→        if &lhs_upper_sqrt * &u128_limit < prime {
   298→            // Make sure `lhs_upper_sqrt < 2**128`, since the value bounded by root is range
   299→            // checked.
   300→            require(lhs_upper_sqrt < u128_limit)?;
   301→            return Some(Self::KnownSmallLhs { lhs_upper_sqrt });
   302→        }
   303→        // No algorithm found.
   304→        None
   305→    }
   306→}
