    44→#[derive(Error, Debug, Eq, PartialEq)]
    45→pub enum Felt252SerdeError {
    46→    #[error("Illegal bigint value during serialization.")]
    47→    BigIntOutOfBounds,
    48→    #[error("Invalid input for deserialization.")]
    49→    InvalidInputForDeserialization,
    50→    #[error(
    51→        "Id `{0}` is too long for serialization. It is longer than {SHORT_STRING_BOUND} \
    52→         characters. Consider adding it in SERDE_SUPPORTED_LONG_IDS."
    53→    )]
    54→    GenericIdTooLong(String),
    55→    #[error("Invalid order of type declarations for serialization.")]
    56→    OutOfOrderTypeDeclarationsForSerialization,
    57→    #[error("Invalid order of libfunc declarations for serialization.")]
    58→    OutOfOrderLibfuncDeclarationsForSerialization,
    59→    #[error("Invalid order of user functions declarations for serialization.")]
    60→    OutOfOrderUserFunctionDeclarationsForSerialization,
    61→    #[error("Invalid function declaration for serialization.")]
    62→    FunctionArgumentsMismatchInSerialization,
    63→}
