    65→/// Serializes a Sierra program and the current compiler and Sierra versions into a vector of
    66→/// felt252s.
    67→pub fn sierra_to_felt252s(
    68→    sierra_version: VersionId,
    69→    compiler_version: VersionId,
    70→    program: &Program,
    71→) -> Result<Vec<BigUintAsHex>, Felt252SerdeError> {
    72→    let mut serialized_program = vec![];
    73→    program.serialize(&mut serialized_program)?;
    74→    let mut serialized = vec![];
    75→    sierra_version.serialize(&mut serialized)?;
    76→    compiler_version.serialize(&mut serialized)?;
    77→    compress(&serialized_program, &mut serialized);
    78→    Ok(serialized)
    79→}
    80→
    81→/// Partially deserializes a Sierra program represented as a slice of felt252s.
    82→///
    83→/// Returns (sierra_version_id, compiler_version_id, remaining),
    84→/// where 'remaining' are all the felts other than the ones dedicated to the version, unprocessed.
    85→/// See [crate::compiler_version].
    86→// TODO(orizi): Validate that changing this function is ok, and make it iterator based as well.
    87→pub fn version_id_from_felt252s(
    88→    sierra_program: &[BigUintAsHex],
    89→) -> Result<(VersionId, VersionId, &[BigUintAsHex]), Felt252SerdeError> {
    90→    let mut iter = sierra_program.iter().map(|v| &v.value);
    91→    let sierra_version_id = VersionId::deserialize(&mut iter)?;
    92→    let compiler_version_id = VersionId::deserialize(&mut iter)?;
    93→    Ok((sierra_version_id, compiler_version_id, &sierra_program[6..]))
    94→}
    95→
    96→/// Deserializes a Sierra program represented as a slice of felt252s.
    97→///
    98→/// Returns (sierra_version_id, compiler_version_id, program).
    99→/// See [crate::compiler_version].
   100→pub fn sierra_from_felt252s(
   101→    sierra_program: &[BigUintAsHex],
   102→) -> Result<(VersionId, VersionId, Program), Felt252SerdeError> {
   103→    let (sierra_version_id, compiler_version_id, remaining) =
   104→        version_id_from_felt252s(sierra_program)?;
   105→    let mut iter =
   106→        decompress(remaining).ok_or(Felt252SerdeError::InvalidInputForDeserialization)?.into_iter();
   107→    Ok((sierra_version_id, compiler_version_id, Program::deserialize(&mut iter)?))
   108→}
   109→
   110→/// Trait for serializing and deserializing into a felt252 vector.
   111→trait Felt252Serde: Sized {
   112→    fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError>;
   113→    fn deserialize<'a, I: ExactSizeIterator<Item = &'a BigUint>>(
   114→        input: &mut I,
   115→    ) -> Result<Self, Felt252SerdeError>;
   116→}
   117→
   118→// Impls for basic types.
   119→
   120→impl Felt252Serde for usize {
   121→    fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError> {
   122→        output.push(BigUintAsHex { value: (*self).into() });
   123→        Ok(())
   124→    }
   125→
   126→    fn deserialize<'a, I: ExactSizeIterator<Item = &'a BigUint>>(
   127→        input: &mut I,
   128→    ) -> Result<Self, Felt252SerdeError> {
   129→        input
   130→            .next()
   131→            .and_then(|size| size.to_usize())
   132→            .ok_or(Felt252SerdeError::InvalidInputForDeserialization)
   133→    }
   134→}
   135→
   136→impl Felt252Serde for u64 {
   137→    fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError> {
   138→        output.push(BigUintAsHex { value: (*self).into() });
   139→        Ok(())
   140→    }
   141→
   142→    fn deserialize<'a, I: ExactSizeIterator<Item = &'a BigUint>>(
   143→        input: &mut I,
   144→    ) -> Result<Self, Felt252SerdeError> {
   145→        input
   146→            .next()
   147→            .and_then(|size| size.to_u64())
   148→            .ok_or(Felt252SerdeError::InvalidInputForDeserialization)
   149→    }
   150→}
   151→
   152→impl<T: Felt252Serde> Felt252Serde for Vec<T> {
   153→    fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError> {
   154→        self.len().serialize(output)?;
   155→        for e in self {
   156→            e.serialize(output)?;
   157→        }
   158→        Ok(())
   159→    }
   160→
   161→    fn deserialize<'a, I: ExactSizeIterator<Item = &'a BigUint>>(
   162→        input: &mut I,
   163→    ) -> Result<Self, Felt252SerdeError> {
   164→        let size = usize::deserialize(input)?;
   165→        let mut result = vec_with_bounded_capacity(size, input.len())?;
   166→        for _ in 0..size {
   167→            result.push(T::deserialize(input)?);
   168→        }
   169→        Ok(result)
   170→    }
   171→}
   172→
   173→impl Felt252Serde for BigInt {
   174→    fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError> {
   175→        output.push(BigUintAsHex {
   176→            value: self.to_biguint().ok_or(Felt252SerdeError::BigIntOutOfBounds)?,
   177→        });
   178→        Ok(())
   179→    }
   180→    fn deserialize<'a, I: ExactSizeIterator<Item = &'a BigUint>>(
   181→        input: &mut I,
   182→    ) -> Result<Self, Felt252SerdeError> {
   183→        Ok(input.next().ok_or(Felt252SerdeError::InvalidInputForDeserialization)?.clone().into())
   184→    }
   185→}
   186→
   187→impl Felt252Serde for StatementIdx {
   188→    fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError> {
   189→        self.0.serialize(output)
   190→    }
   191→    fn deserialize<'a, I: ExactSizeIterator<Item = &'a BigUint>>(
   192→        input: &mut I,
   193→    ) -> Result<Self, Felt252SerdeError> {
   194→        Ok(Self(usize::deserialize(input)?))
   195→    }
   196→}
