   221→macro_rules! generic_id_serde {
   222→    ($Obj:ident) => {
   223→        impl Felt252Serde for $Obj {
   224→            fn serialize(&self, output: &mut Vec<BigUintAsHex>) -> Result<(), Felt252SerdeError> {
   225→                output.push(BigUintAsHex {
   226→                    value: if self.0.len() <= SHORT_STRING_BOUND {
   227→                        BigUint::from_bytes_be(self.0.as_bytes())
   228→                    } else {
   229→                        if !SERDE_SUPPORTED_LONG_IDS.contains(self.0.as_str()) {
   230→                            return Err(Felt252SerdeError::GenericIdTooLong(self.0.to_string()));
   231→                        }
   232→                        starknet_keccak(self.0.as_bytes())
   233→                    },
   234→                });
   235→                Ok(())
   236→            }
   237→            fn deserialize<'a, I: ExactSizeIterator<Item = &'a BigUint>>(
   238→                input: &mut I,
   239→            ) -> Result<Self, Felt252SerdeError> {
   240→                input
   241→                    .next()
   242→                    .and_then(|id| {
   243→                        LONG_NAME_FIX.get(&id).map(|s| Self(SmolStr::new(s))).or_else(|| {
   244→                            std::str::from_utf8(&id.to_bytes_be()).ok().map(|s| Self(s.into()))
   245→                        })
   246→                    })
   247→                    .ok_or(Felt252SerdeError::InvalidInputForDeserialization)
   248→            }
   249→        }
   250→    };
   251→}
